async function m4ExpectQualityProjectLineage(
  runtime: Fixture,
  projectId: string,
) {
  const storage = runtime.qualityLineageStorage(),
    allocations = runtime.allocationCounts(),
    events = runtime.domainEvents(),
    response = await runtime.request(
      `/api/v2/exports/projects/${projectId}/json`,
    );
  expect(response.status, await response.clone().text()).toBe(200);
  const packet = JSON.parse(
      ((await response.json()) as { content: string }).content,
    ),
    lineage = ProjectPackageLineageSchema.parse(packet.lineage).quality;
  if (!lineage || lineage.state !== "available")
    throw Error("Original saved quality owner metadata required");
  expect(lineage.coverage).toBe(
    "recorded-quality-model-and-local-owner-rows-only",
  );
  for (const [category, table] of [
    ["reports", "narrative_quality_reports"],
    ["localReviews", "narrative_local_quality_reviews"],
  ] as const) {
    const rows = storage[table]!.filter((row) => row.project_id === projectId);
    expect(lineage[category].map((item) => item.id)).toEqual(
      rows.map((row) => row.id),
    );
    for (const row of rows) {
      const item = lineage[category].find((item) => item.id === row.id)!,
        value = JSON.parse(String(row.value_json)),
        basis = category === "reports" ? value.basis : value.source.basis,
        content = value.content;
      expect(item).toMatchObject({
        id: row.id,
        projectId,
        version: row.version,
        status: value.status,
        basis: { request: basis.request, references: basis.references },
        createdAt: row.created_at,
        updatedAt: row.updated_at,
        fingerprint: {
          format: "derived-original-quality-value-json-bytes-v1",
          sha256: createHash("sha256")
            .update(String(row.value_json))
            .digest("hex"),
        },
        observation: "saved-quality-owner-row-not-full-state-history",
        semanticVerification: "unverified",
      });
      const issues = content.issues ?? content.findings;
      expect(item.issues).toEqual(
        issues.map(
          ({
            id,
            category,
            severity,
            source,
            evidence,
            ruleId,
          }: {
            id: string;
            category: string;
            severity: string;
            source: string;
            evidence: { quote: string }[];
            ruleId?: string;
          }) => ({
            id,
            category,
            severity,
            source,
            ...(ruleId ? { ruleId } : {}),
            evidence: evidence.map(({ quote, ...ref }) => ({
              ...ref,
              quoteHash: createHash("sha256").update(quote).digest("hex"),
              quoteCharacters: quote.length,
            })),
          }),
        ),
      );
      expect(item.dispositions).toEqual(
        value.dispositions.map(
          ({ note: _private, ...decision }: Record<string, unknown>) =>
            decision,
        ),
      );
      if (category === "reports")
        expect(item).toMatchObject({
          kind: "model-report",
          workflowId: value.workflowId,
          baseReportId: basis.baseReportId,
          sourceSnapshotId: value.sourceSnapshotId,
          runIds: value.runIds,
          engineKind: value.engineKind,
          usage: value.usage,
        });
      else
        expect(item).toMatchObject({
          kind: "local-review",
          origin: value.origin,
          sourceFingerprint: value.source.sourceFingerprint,
          baseReviewId: value.source.baseReviewId,
          qualityState: "unverified",
        });
      if (content.reviewedDimensions)
        expect(item.reviewedDimensions).toEqual(content.reviewedDimensions);
      else {
        expect(item).not.toHaveProperty("reviewedDimensions");
        expect(item).toMatchObject({
          checkedRules: content.checkedRules,
          semanticCoverage: "not-assessed",
        });
      }
      expect(item).not.toHaveProperty("content");
      expect(item).not.toHaveProperty("isCurrent");
      expect(item).not.toHaveProperty("sourceState");
      expect(item).not.toHaveProperty("blockers");
    }
  }
  for (const forbidden of [
    "PRIVATE",
    "原正文保留。",
    "原文里的逐字重复",
    "preparedPrompt",
    "staleReasons",
    "sourceReasons",
    "legacyFields",
  ])
    expect(JSON.stringify(lineage)).not.toContain(forbidden);
  expect(runtime.qualityLineageStorage()).toEqual(storage);
  expect(runtime.allocationCounts()).toEqual(allocations);
  expect(runtime.domainEvents()).toEqual(events);
  return lineage;
}
import { WORKSPACE_PROJECT_LINEAGE_SERVICE } from "@dramaip/contracts/creation-project-lineage";
async function m4ExpectWorkspaceIntentLineage(
  runtime: Fixture,
  projectId: string,
) {
  const storage = runtime.workspaceIntentLineageStorage(),
    allocations = runtime.allocationCounts(),
    events = runtime.domainEvents();
  const response = await runtime.request(
    `/api/v2/exports/projects/${projectId}/json`,
  );
  expect(response.status, await response.clone().text()).toBe(200);
  const packet = JSON.parse(
      ((await response.json()) as { content: string }).content,
    ),
    lineage = ProjectPackageLineageSchema.parse(packet.lineage).workspace;
  if (!lineage || lineage.state !== "available")
    throw Error("Original saved author intent owner metadata required");
  expect(lineage.coverage).toBe("recorded-workspace-author-intent-rows-only");
  const rows = storage.intents.filter((row) => row.project_id === projectId);
  expect(lineage.authorIntents.map((item) => item.id)).toEqual(
    [...rows]
      .sort((a, b) => Number(b.version) - Number(a.version))
      .map((row) => row.id),
  );
  for (const row of rows) {
    const item = lineage.authorIntents.find((item) => item.id === row.id)!,
      source = JSON.parse(String(row.source_json));
    expect(item).toMatchObject({
      kind: "author-intent",
      id: row.id,
      projectId,
      version: row.version,
      stateVersion: row.state_version,
      status: row.status,
      source: { kind: source.kind, projectVersion: source.projectVersion },
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      observation: "saved-author-intent-row-not-full-state-history",
      semanticVerification: "unverified",
      fingerprints: {
        content: {
          format: "derived-original-intent-content-json-bytes-v1",
          sha256: createHash("sha256")
            .update(String(row.content_json))
            .digest("hex"),
        },
        source: {
          format: "derived-original-intent-source-json-bytes-v1",
          sha256: createHash("sha256")
            .update(String(row.source_json))
            .digest("hex"),
        },
      },
    });
    if (row.base_adopted_id)
      expect(item.baseAdoptedId).toBe(row.base_adopted_id);
    else expect(item).not.toHaveProperty("baseAdoptedId");
    if (row.adopted_at) expect(item.adoptedAt).toBe(row.adopted_at);
    else expect(item).not.toHaveProperty("adoptedAt");
    if (source.kind === "ai-generated")
      expect(item.source).toEqual({
        kind: source.kind,
        projectVersion: source.projectVersion,
        creation: {
          workflowId: source.creation.workflowId,
          sourceSnapshotId: source.creation.sourceSnapshotId,
          runIds: source.creation.runIds,
          engineKind: source.creation.engineKind,
          request: source.creation.basis.request,
          references: source.creation.basis.references,
        },
      });
    else
      expect(item.source).toEqual({
        kind: source.kind,
        projectVersion: source.projectVersion,
      });
  }
  const text = JSON.stringify(lineage);
  for (const forbidden of [
    "PRIVATE",
    "legacyFields",
    "sourceState",
    "isCurrent",
    "preparedPrompt",
    "/Users/",
  ])
    expect(text).not.toContain(forbidden);
  for (const item of lineage.authorIntents)
    expect(item).not.toHaveProperty("content");
  expect(runtime.workspaceIntentLineageStorage()).toEqual(storage);
  expect(runtime.allocationCounts()).toEqual(allocations);
  expect(runtime.domainEvents()).toEqual(events);
  return lineage;
}
async function m4RejectCorruptOriginalAiIntentLineage(
  runtime: Fixture,
  projectId: string,
) {
  const original = await m4ExpectWorkspaceIntentLineage(runtime, projectId),
    saved = runtime.workspaceIntentLineageStorage(),
    row = saved.intents.find(
      (row) =>
        row.project_id === projectId &&
        JSON.parse(String(row.source_json)).kind === "ai-generated",
    )!,
    source = JSON.parse(String(row.source_json)),
    versions: Record<string, unknown>[] = [];
  const wrongProject = structuredClone(source);
  wrongProject.creation.basis.references.find(
    (ref: { sourceKind: string }) => ref.sourceKind === "project",
  ).sourceId = crypto.randomUUID();
  versions.push(wrongProject);
  const wrongVersion = structuredClone(source);
  wrongVersion.projectVersion++;
  versions.push(wrongVersion);
  const duplicate = structuredClone(source);
  duplicate.creation.basis.references.push(
    duplicate.creation.basis.references[0],
  );
  versions.push(duplicate);
  const privatePath = structuredClone(source);
  privatePath.creation.basis.references[0].fieldPath =
    "/Users/PRIVATE/source.txt";
  versions.push(privatePath);
  if (source.creation.basis.sourceBasis) {
    const foreign = structuredClone(source);
    foreign.creation.basis.sourceBasis.projectId = crypto.randomUUID();
    versions.push(foreign);
  }
  const allocations = runtime.allocationCounts(),
    events = runtime.domainEvents();
  for (const value of versions) {
    const restore = runtime.corruptWorkspaceIntentLineage(String(row.id), {
      source_json: JSON.stringify(value),
    });
    try {
      const corrupted = runtime.workspaceIntentLineageStorage(),
        response = await runtime.request(
          `/api/v2/exports/projects/${projectId}/json`,
        );
      expect(response.status).toBe(409);
      expect(await response.text()).not.toContain("PRIVATE");
      expect(
        (
          await runtime.request(
            `/api/v2/exports/projects/${projectId}/submission-markdown`,
          )
        ).status,
      ).toBe(200);
      expect(runtime.workspaceIntentLineageStorage()).toEqual(corrupted);
      expect(runtime.allocationCounts()).toEqual(allocations);
      expect(runtime.domainEvents()).toEqual(events);
    } finally {
      restore();
    }
    expect(await m4ExpectWorkspaceIntentLineage(runtime, projectId)).toEqual(
      original,
    );
  }
  expect(runtime.workspaceIntentLineageStorage()).toEqual(saved);
}
