async function m4ExpectStoredKnowledgeLineage(
  runtime: Fixture,
  projectId: string,
) {
  const lineage = await m4ReadKnowledgePackageLineage(runtime, projectId),
    rows = runtime.knowledgeLineageStorage();
  const declarations = rows.knowledge_story_declarations!.filter(
    (row) => (row as { project_id: string }).project_id === projectId,
  ) as Record<string, unknown>[];
  const assertions = rows.knowledge_story_assertions!.filter(
    (row) => (row as { project_id: string }).project_id === projectId,
  ) as Record<string, unknown>[];
  const transitions = rows.knowledge_story_source_transitions!.filter(
    (row) => (row as { project_id: string }).project_id === projectId,
  ) as Record<string, unknown>[];
  expect(lineage.declarations).toHaveLength(declarations.length);
  expect(lineage.assertions).toHaveLength(assertions.length);
  expect(lineage.transitions).toHaveLength(transitions.length);
  for (const [kind, originalRows, output] of [
    ["declaration", declarations, lineage.declarations],
    ["assertion", assertions, lineage.assertions],
  ] as const) {
    for (const row of originalRows) {
      const item = output.find((value) => value.id === row.id)!;
      expect(item).toMatchObject({
        kind,
        id: row.id,
        projectId,
        version: row.version,
        status: row.status,
        createdAt: row.created_at,
        updatedAt: row.updated_at,
        semanticVerification: "unverified",
        observation: "saved-owner-receipt-not-full-version-history",
      });
      const basis = JSON.parse(String(row.basis_json)),
        source = kind === "declaration" ? basis : basis.sourceBasis;
      expect(item.sourceBasis).toEqual({
        fingerprint: source.fingerprint,
        policyDependencies: source.policyDependencies,
        sources: source.sources.map(
          ({
            selection,
            quote,
            quoteHash,
            anchors,
          }: {
            selection: unknown;
            quote: string;
            quoteHash: string;
            anchors: unknown[];
          }) => ({
            selection,
            quoteHash,
            quoteCharacters: quote.length,
            anchors,
          }),
        ),
      });
      const id = kind === "declaration" ? row.adopted_node_id : row.adopted_id;
      if (id)
        expect(item.adoptedRecord).toEqual({
          kind: kind === "declaration" ? "node" : row.adopted_kind,
          id,
          version:
            kind === "declaration"
              ? row.adopted_node_version
              : row.adopted_version,
        });
      else expect(item).not.toHaveProperty("adoptedRecord");
    }
  }
  for (const row of transitions) {
    const item = lineage.transitions.find(
      (value) =>
        value.id === row.source_id &&
        value.sourceKind === row.source_kind &&
        value.version === row.version,
    )!;
    const original = JSON.parse(String(row.original_record_json));
    expect(item).toMatchObject({
      id: row.source_id,
      projectId,
      sourceKind: row.source_kind,
      version: row.version,
      action: row.action,
      record: {
        kind: row.record_kind,
        id: row.record_id,
        version: row.record_version,
      },
      original: {
        kind: row.record_kind,
        id: original.id,
        version: original.version,
      },
      retiredAt: row.retired_at,
      createdAt: row.created_at,
      fingerprint: {
        format: "derived-from-original-retired-row-v1",
        sha256: createHash("sha256")
          .update(String(row.original_record_json))
          .digest("hex"),
      },
    });
    if (row.replacement_id) expect(item.replacementId).toBe(row.replacement_id);
    else expect(item).not.toHaveProperty("replacementId");
    expect(item).not.toHaveProperty("reason");
    expect(item).not.toHaveProperty("original_record_json");
  }
  return lineage;
}
