async function m4ExpectOriginalHumanPair(
  runtime: Fixture,
  projectId: string,
  refs: {
    outline: { id: string; version: number };
    script: { id: string; version: number };
  },
) {
  const lineage = await m4ReadProductionPackageLineage(runtime, projectId);
  for (const ref of [refs.outline, refs.script]) {
    const response = await runtime.request(
      "/api/v2/episode-development/" + ref.id,
    );
    expect(response.status, await response.clone().text()).toBe(200);
    const original = (await response.json()) as EpisodeDevelopmentResult,
      confirmation = original.topologyRevision ?? original.sourceRevision;
    if (!confirmation) throw Error("Actual persisted human pair required");
    const exported = lineage.results.find(
      (item: { id: string }) => item.id === ref.id,
    );
    expect(exported).toMatchObject({
      id: original.id,
      version: original.version,
      origin: original.origin,
      runIds: [],
      sourceSnapshotId: original.sourceSnapshotId,
      authorConfirmation: {
        kind: original.origin,
        previewId: confirmation.previewId,
        sourceScript: confirmation.sourceScript,
        sourceOutline: confirmation.sourceOutline,
        document: confirmation.document,
        results: confirmation.results,
        semanticVerification: confirmation.semanticVerification,
      },
    });
    expect(exported).not.toHaveProperty("workflowId");
    expect(exported.references).toEqual(
      original.basis.references.map(
        ({ sourceKind, sourceId, sourceVersion, fieldPath, contentHash }) => ({
          sourceKind,
          sourceId,
          sourceVersion,
          fieldPath,
          contentHash,
        }),
      ),
    );
    if (original.content.kind === "episode-script")
      expect(exported.sceneBlocks).toEqual(original.content.value.sceneLinks);
  }
  return lineage.results;
}
async function m4ReadMergeLineage(
  runtime: Fixture,
  projectId: string,
  workflowId: string,
) {
  const before = runtime.allocationCounts();
  const response = await runtime.request(
    `/api/v2/exports/projects/${projectId}/json`,
  );
  expect(response.status, await response.clone().text()).toBe(200);
  const packet = JSON.parse(
    ((await response.json()) as { content: string }).content,
  );
  expect(runtime.allocationCounts()).toEqual(before);
  return packet.lineage.workflows.items.find(
    (item: { id: string }) => item.id === workflowId,
  );
}
