  it("render catalog reads real scoped pagination and original request receipts without initializing timelines or touching Host", async () => {
    let healthCalls = 0;
    const host = renderHost(async () => {
      healthCalls++;
    });
    const runtime = await fixture(host);
    const empty = await seed(runtime);
    const before = runtime.allocationCounts();
    const events = runtime.domainEvents();
    const path = `/api/v2/episodes/${empty.episode.id}/timeline-renders?projectId=${empty.project.id}`;
    const response = await runtime.request(path);
    expect(response.status).toBe(200);
    expect(response.headers.get("Cache-Control")).toBe("no-store");
    expect(response.headers.get("ETag")).toBeTruthy();
    expect(await response.json()).toEqual({
      projectId: empty.project.id,
      episodeId: empty.episode.id,
      items: [],
    });
    expect(runtime.allocationCounts()).toEqual(before);
    expect(runtime.domainEvents()).toEqual(events);
    expect(healthCalls).toBe(0);
    const source = await prepareRender(runtime);
    const preflight = await renderPreflightRead(runtime, source.timeline.id);
    const keys = [
      crypto.randomUUID(),
      crypto.randomUUID(),
      crypto.randomUUID(),
    ];
    const jobs = [];
    for (const key of keys)
      jobs.push(
        await (
          await renderCreate(
            runtime,
            source.timeline,
            renderInput(preflight),
            key,
          )
        ).json(),
      );
    const stable = runtime.renderStorage();
    const facts = runtime.domainEvents();
    const calls = healthCalls;
    const base = `/api/v2/episodes/${source.episode.id}/timeline-renders?projectId=${source.project.id}`;
    let cursor: string | undefined;
    const ids: string[] = [];
    do {
      const page = await read<
        import("@dramaip/contracts/timeline").TimelineRenderCatalog
      >(runtime, `${base}&limit=1${cursor ? `&cursor=${cursor}` : ""}`);
      expect(page.timeline).toEqual({
        id: source.timeline.id,
        version: source.timeline.version,
        etag: `"timeline:${source.timeline.id}:${source.timeline.version}"`,
      });
      ids.push(...page.items.map((item) => item.jobId));
      cursor = page.nextCursor;
    } while (cursor);
    expect(new Set(ids)).toEqual(new Set(jobs.map((job) => job.jobId)));
    const requestFingerprint = createHash("sha256")
      .update(keys[0]!)
      .digest("hex");
    const found = await read<
      import("@dramaip/contracts/timeline").TimelineRenderCatalog
    >(runtime, `${base}&requestFingerprint=${requestFingerprint}`);
    expect(found.items).toHaveLength(1);
    expect(found.items[0]!.jobId).toBe(jobs[0].jobId);
    expect(found.items[0]).not.toHaveProperty("idempotencyKey");
    const first = await read<
      import("@dramaip/contracts/timeline").TimelineRenderCatalog
    >(runtime, `${base}&limit=1`);
    expect(
      (await runtime.request(`${path}&cursor=${first.nextCursor}`)).status,
    ).toBe(400);
    expect((await runtime.request(`${base}&limit=0`)).status).toBe(400);
    expect(
      (await runtime.request(`${base}&cursor=not-an-actual-cursor`)).status,
    ).toBe(400);
    expect(
      (
        await runtime.request(
          `/api/v2/episodes/${source.episode.id}/timeline-renders?projectId=${empty.project.id}`,
        )
      ).status,
    ).toBe(404);
    const falsified = JSON.parse(
      Buffer.from(first.nextCursor!, "base64url").toString(),
    );
    falsified[5] = crypto.randomUUID();
    expect(
      (
        await runtime.request(
          `${base}&cursor=${Buffer.from(JSON.stringify(falsified)).toString("base64url")}`,
        )
      ).status,
    ).toBe(400);
    expect(runtime.renderStorage()).toEqual(stable);
    expect(runtime.domainEvents()).toEqual(facts);
    expect(healthCalls).toBe(calls);
  });

