  it("render archive receipts only deduplicate the exact owner, descriptor and lineage; collisions never publish foreign output", async () => {
    const host = renderHost();
    const runtime = await fixture(host);
    const source = await prepareRender(runtime);
    const other = await seed(runtime);
    const descriptor = {
      mediaRef: crypto.randomUUID(),
      kind: "video" as const,
      mimeType: "video/mp4" as const,
      extension: ".mp4" as const,
      sizeBytes: 100,
      sha256: "c".repeat(64),
      width: 1080,
      height: 1920,
      durationFrames: source.timeline.durationFrames,
      frameRate: source.timeline.profile.frameRate,
      status: "archived" as const,
    };
    const input = {
      projectId: other.project.id,
      parentId: other.episode.id,
      title: "真实旧归档",
      descriptor,
      lineage: { source: "actual-old" },
    };
    const registered = runtime.registerArtifact(input);
    const facts = runtime.domainEvents();
    expect(
      runtime.registerArtifact({ ...input, lineage: { source: "actual-old" } })
        .id,
    ).toBe(registered.id);
    for (const changed of [
      { ...input, projectId: source.project.id },
      { ...input, parentId: source.episode.id },
      { ...input, descriptor: { ...descriptor, sha256: "d".repeat(64) } },
      { ...input, title: "不同输出" },
      { ...input, lineage: { source: "forged" } },
    ])
      expect(() => runtime.registerArtifact(changed)).toThrow("归档回执");
    expect(runtime.domainEvents()).toEqual(facts);
    host.startTimelineRender = async (value) => ({
      jobId: value.jobId,
      status: "succeeded",
      progress: 1,
      rendererVersion: "controlled-signed-v1",
      sidecarArtifactVersion: "controlled-signed-v1",
      output: descriptor,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    const preflight = await renderPreflightRead(runtime, source.timeline.id);
    const job = await (
      await renderCreate(runtime, source.timeline, renderInput(preflight))
    ).json();
    expect(job.status).toBe("failed");
    expect(job.failureCode).toBe("OUTPUT_ARCHIVE_CONFLICT");
    expect(job).not.toHaveProperty("outputRecord");
    expect(job).not.toHaveProperty("outputMediaRef");
    expect(
      await read(
        runtime,
        `/api/v2/video?projectId=${source.project.id}&parentId=${source.episode.id}`,
      ),
    ).toEqual([]);
    runtime.playbackArchiveStatus(registered.id, "quarantined");
    expect(() => runtime.registerArtifact(input)).toThrow("归档回执");
  });

