  it("media pending summaries paginate actual owner rows, bind cursors to real scope, expose only identity/counts and remain read-only across SQLite restart", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-media-pending-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let runtime = await fixture(undefined, undefined, path);
    const { source, original, timeline } = await assembledAudio(runtime);
    const other = await seed(runtime);
    const created = await post(runtime, "/api/v2/shot-stills", {
      projectId: source.project.id,
      parentId: source.shot.id,
      title: "PRIVATE source",
      payload: { 预览数据: "PRIVATE ACTUAL BYTES" },
    });
    const record = (await created.json()) as MediaRecord;
    const expected: Record<string, Set<string>> = {
      "media-source-review-summaries": new Set(),
      "audio-revision-summaries": new Set(),
      "audio-resolution-summaries": new Set(),
    };
    for (let index = 0; index < 3; index++) {
      const sourceReview = await post(
        runtime,
        `/api/v2/media-records/${record.id}/source-reviews`,
        {
          recordVersion: record.version,
          shotId: source.shot.id,
          shotVersion: source.shot.version,
        },
        crypto.randomUUID(),
      );
      expect(sourceReview.status).toBe(200);
      expected["media-source-review-summaries"]!.add(
        ((await sourceReview.json()) as MediaSourceReview).id,
      );
      const revision = await audioRevisionPreview(runtime, original);
      expect(revision.status).toBe(200);
      expected["audio-revision-summaries"]!.add(
        ((await revision.json()) as AudioRevision).id,
      );
      const resolution = await resolutionPreview(runtime, timeline, [
        {
          action: "remove",
          clipId: timeline.tracks.find((item) => item.kind === "dialogue")!
            .clips[0]!.id,
          reason: "PRIVATE intentional reason",
        },
      ]);
      expect(resolution.status).toBe(200);
      expected["audio-resolution-summaries"]!.add(
        ((await resolution.json()) as AudioResolution).id,
      );
    }
    const persisted = runtime.mediaPendingStorage();
    const events = runtime.domainEvents();
    const pagesBefore: Record<string, unknown> = {};
    let foreignOwnerCursor: string | undefined;
    for (const [name, ids] of Object.entries(expected)) {
      const endpoint = `/api/v2/projects/${source.project.id}/${name}`;
      const first = await runtime.request(`${endpoint}?limit=1`);
      expect(first.status).toBe(200);
      expect(first.headers.get("etag")).toMatch(/^"[a-f0-9]{64}"$/u);
      const page = (await first.json()) as {
        items: Array<Record<string, unknown>>;
        nextCursor: string;
      };
      pagesBefore[name] = await read(runtime, endpoint);
      const serial = JSON.stringify(pagesBefore[name]);
      for (const forbidden of [
        "PRIVATE",
        '"payload"',
        '"original"',
        '"candidate"',
        '"clips"',
        '"before"',
        '"after"',
        '"confirmation"',
        '"reasons"',
        '"staleReasons"',
        '"contentHash"',
        '"clipLinks"',
        '"sourceFingerprint"',
      ])
        expect(serial).not.toContain(forbidden);
      expect(page.items).toHaveLength(1);
      expect(page.nextCursor).toBeTruthy();
      const all = [...page.items];
      let cursor: string | undefined = page.nextCursor;
      while (cursor) {
        const next: {
          items: Array<Record<string, unknown>>;
          nextCursor?: string;
        } = await read<{
          items: Array<Record<string, unknown>>;
          nextCursor?: string;
        }>(runtime, `${endpoint}?limit=1&cursor=${encodeURIComponent(cursor)}`);
        all.push(...next.items);
        cursor = next.nextCursor;
      }
      expect(new Set(all.map((value) => value.id))).toEqual(ids);
      expect(all).toHaveLength(3);
      expect(all.every((value) => value.projectId === source.project.id)).toBe(
        true,
      );
      expect(
        await read(runtime, `/api/v2/projects/${other.project.id}/${name}`),
      ).toEqual({ items: [] });
      const tuple = JSON.parse(
        Buffer.from(page.nextCursor, "base64url").toString(),
      ) as string[];
      for (const invalid of [
        "invalid",
        Buffer.from(
          JSON.stringify([...tuple.slice(0, 3), crypto.randomUUID()]),
        ).toString("base64url"),
        Buffer.from(
          JSON.stringify([
            tuple[0],
            tuple[1],
            "2000-01-01T00:00:00.000Z",
            tuple[3],
          ]),
        ).toString("base64url"),
        ...(foreignOwnerCursor ? [foreignOwnerCursor] : []),
      ]) {
        const failed = await runtime.request(
          `${endpoint}?cursor=${encodeURIComponent(invalid)}`,
        );
        expect(failed.status).toBe(400);
        expect(failed.headers.get("content-type")).toContain(
          "application/problem+json",
        );
        expect(JSON.stringify(await failed.json())).not.toContain("PRIVATE");
      }
      expect(
        (
          await runtime.request(
            `/api/v2/projects/${other.project.id}/${name}?cursor=${page.nextCursor}`,
          )
        ).status,
      ).toBe(400);
      expect(
        (
          await runtime.request(
            `/api/v2/projects/${crypto.randomUUID()}/${name}`,
          )
        ).status,
      ).toBe(404);
      for (const limit of [0, 101, 1.5, "bad"])
        expect(
          (await runtime.request(`${endpoint}?limit=${limit}`)).status,
        ).toBe(400);
      foreignOwnerCursor = page.nextCursor;
    }
    expect(runtime.mediaPendingStorage()).toEqual(persisted);
    expect(runtime.domainEvents()).toEqual(events);
    await runtime.close();
    runtime = await fixture(undefined, undefined, path);
    for (const name of Object.keys(expected))
      expect(
        await read(runtime, `/api/v2/projects/${source.project.id}/${name}`),
      ).toEqual(pagesBefore[name]);
    expect(runtime.mediaPendingStorage()).toEqual(persisted);
    expect(runtime.domainEvents()).toEqual(events);
  });

