  it("audio resolution requires separate explicit subtitle text selection and rejects unrelated, foreign, duplicate or ordinary-video mapping before any allocation", async () => {
    const runtime = await fixture();
    const { source, original, timeline } = await assembledAudio(runtime);
    const latest = await reviseAndAdopt(runtime, original);
    const other = await audioDraft(runtime, source, { durationSeconds: 4 });
    const unrelated = await adoptAudio(runtime, other);
    expect(unrelated.status).toBe(200);
    const foreign = await assembledAudio(runtime);
    const catalog = await read<AudioResolutionOptions>(
      runtime,
      `/api/v2/timelines/${timeline.id}/audio-source-options`,
    );
    const changes = replacementChanges(catalog);
    expect(
      changes.every(
        (item) =>
          item.action === "replace" && item.audioTrackId === latest.track.id,
      ),
    ).toBe(true);
    const subtitle = catalog.items.find((item) => item.kind === "subtitle")!;
    const state = runtime.audioResolutionStorage(timeline.id);
    const events = runtime.domainEvents();
    for (const invalid of [
      [changes[0]!, changes[0]!],
      [
        {
          action: "replace",
          clipId: changes[0]!.clipId,
          audioTrackId: other.id,
          sourceClipId: other.clips[0]!.id,
          subtitleText: "keep",
        },
      ],
      [
        {
          action: "replace",
          clipId: changes[0]!.clipId,
          audioTrackId: foreign.original.id,
          sourceClipId: foreign.original.clips[0]!.id,
          subtitleText: "keep",
        },
      ],
      [
        {
          action: "remove",
          clipId: timeline.tracks.find((item) => item.kind === "video")!
            .clips[0]!.id,
          reason: "ordinary video",
        },
      ],
      [
        {
          ...changes.find((item) => item.clipId !== subtitle.clip.id)!,
          subtitleText: "replacement",
        },
      ],
    ]) {
      const result = await resolutionPreview(
        runtime,
        timeline,
        invalid as AudioResolutionInput["changes"],
      );
      expect([400, 409]).toContain(result.status);
    }
    expect(
      (
        await resolutionPreview(
          runtime,
          timeline,
          changes,
          crypto.randomUUID(),
          999,
        )
      ).status,
    ).toBe(412);
    expect(
      (
        await runtime.request(
          `/api/v2/timelines/${timeline.id}/audio-resolution-previews`,
          {
            method: "POST",
            body: JSON.stringify({
              timelineVersion: timeline.version,
              changes,
            }),
          },
        )
      ).status,
    ).toBe(428);
    expect(runtime.audioResolutionStorage(timeline.id)).toEqual(state);
    expect(runtime.domainEvents()).toEqual(events);
    const keep = (await (
      await resolutionPreview(runtime, timeline, changes)
    ).json()) as AudioResolution;
    expect(
      keep.after.tracks.find((item) => item.kind === "subtitle")!.clips[0]!
        .text,
    ).toBe(subtitle.clip.text);
    const replace = (await (
      await resolutionPreview(
        runtime,
        timeline,
        changes.map((item) =>
          item.clipId === subtitle.clip.id
            ? ({
                ...item,
                subtitleText: "replacement",
              } as AudioResolutionInput["changes"][number])
            : item,
        ),
      )
    ).json()) as AudioResolution;
    expect(
      replace.after.tracks.find((item) => item.kind === "subtitle")!.clips[0]!
        .text,
    ).toBe(latest.track.clips[0]!.text);
    expect(
      (await resolutionTransition(runtime, replace, "confirm")).status,
    ).toBe(200);
    expect((await resolutionTransition(runtime, keep, "confirm")).status).toBe(
      409,
    );
    expect((await resolutionTransition(runtime, keep, "discard")).status).toBe(
      200,
    );
  });

