  it("audio source adoption uses ETag, SQLite receipts and current replay projection; legacy proof is never invented", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-audio-sources-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let runtime = await fixture(undefined, undefined, path);
    const source = await seed(runtime);
    const track = await audioDraft(runtime, source);
    expect(
      (
        await runtime.request(`/api/v2/audio-tracks/${track.id}/adopt`, {
          method: "POST",
        })
      ).status,
    ).toBe(428);
    const bad = await adoptAudio(runtime, track, crypto.randomUUID(), 99);
    expect(bad.status).toBe(412);
    expect(bad.headers.get("Content-Type")).toContain(
      "application/problem+json",
    );
    const key = crypto.randomUUID();
    const adopted = await adoptAudio(runtime, track, key);
    expect(adopted.status).toBe(200);
    expect(adopted.headers.get("ETag")).toBe('"1"');
    const value = await adopted.json();
    expect(value).toMatchObject({
      version: 1,
      status: "adopted",
      sourceState: "current",
    });
    const events = runtime.domainEvents();
    expect((await adoptAudio(runtime, track, key)).status).toBe(200);
    expect(runtime.domainEvents()).toEqual(events);
    expect((await adoptAudio(runtime, track, key, 1)).status).toBe(409);
    await runtime.close();
    runtime = await fixture(undefined, undefined, path);
    expect((await audioList(runtime, source.episode.id))[0]).toEqual(value);
    await changeShot(runtime, source.shot);
    const changedEvents = runtime.domainEvents();
    const replay = await adoptAudio(runtime, track, key);
    expect(replay.status).toBe(200);
    expect(await replay.json()).toMatchObject({
      sourceState: "stale",
      version: 1,
    });
    expect((await adoptAudio(runtime, { ...track, version: 1 })).status).toBe(
      409,
    );
    expect(runtime.domainEvents()).toEqual(changedEvents);
    const fresh = await audioDraft(runtime, {
      ...source,
      shot: { ...source.shot, version: 1 },
    });
    runtime.forgetLegacyAudioSource(fresh.id);
    expect(
      (await audioList(runtime, source.episode.id)).find(
        (item) => item.id === fresh.id,
      ),
    ).toMatchObject({
      sourceState: "unverified",
      stale: true,
      version: 0,
      clips: fresh.clips,
    });
    expect((await adoptAudio(runtime, fresh)).status).toBe(409);
    const trackEvents = runtime
      .domainEvents()
      .filter((event) => event.type.startsWith("media.audio-track-"));
    expect(JSON.stringify(trackEvents)).not.toContain("PRIVATE 台词");
  });

