  it("generation costs upgrade untouched legacy amounts, roll back declarations with their event, and reject tampered original observations", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-legacy-cost-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let runtime = await fixture(undefined, undefined, path, false, true);
    const source = await seed(runtime);
    const id = runtime.seedLegacyGeneration(source.project.id, 0.001);
    const unknownId = runtime.seedLegacyGeneration(source.project.id, null);
    await runtime.close();
    runtime = await fixture(undefined, undefined, path);
    const ledger = () =>
      read<Array<Record<string, unknown>>>(
        runtime,
        `/api/v2/projects/${source.project.id}/generation-ledger`,
      );
    const patch = (value: unknown) =>
      runtime.request(`/api/v2/generation-ledger/${id}`, {
        method: "PATCH",
        body: JSON.stringify(value),
      });
    const migrated = runtime.generationCostStorage(id);
    expect(migrated.observations).toEqual([]);
    expect(migrated.events).toEqual([]);
    expect(migrated.record).toMatchObject({
      actual_cost: 0.001,
      currency: "CNY",
      updated_at: "2026-09-01T00:00:00.000Z",
    });
    const legacy = (await ledger()).find((item) => item.id === id)!;
    expect(legacy).not.toHaveProperty("actualCost");
    expect(legacy).toMatchObject({
      costObservationCount: 0,
      costObservation: {
        source: "legacy-unverified",
        billingStatus: "unknown",
        measurementScope: "unspecified",
        amount: { status: "reported", value: 0.001 },
        unit: { status: "unreported" },
      },
    });
    expect(
      (await ledger()).find((item) => item.id === unknownId),
    ).toMatchObject({ costObservation: { amount: { status: "unreported" } } });
    expect(
      (await patch({ costNote: "备注不是金额认证", currency: "USD" })).status,
    ).toBe(200);
    expect(runtime.generationCostStorage(id).observations).toEqual([]);
    const before = runtime.generationCostStorage(id);
    runtime.failGenerationEvents(true);
    expect((await patch({ actualCost: 0 })).status).toBe(500);
    expect(runtime.generationCostStorage(id)).toEqual(before);
    runtime.failGenerationEvents(false);
    const saved = await patch({ actualCost: 0, costNote: "" });
    expect(saved.status, await saved.clone().text()).toBe(200);
    const declaration = await saved.json();
    expect(declaration).not.toHaveProperty("actualCost");
    expect(declaration).toMatchObject({
      costObservationCount: 2,
      costObservation: {
        source: "human-declared",
        amount: { status: "reported", value: 0 },
        unit: { status: "unreported" },
        billingStatus: "unknown",
      },
    });
    expect(declaration).not.toHaveProperty("costNote");
    const storage = runtime.generationCostStorage(id);
    expect(storage.observations).toHaveLength(2);
    expect(
      JSON.parse(storage.observations[0]!.value_json as string),
    ).toMatchObject({
      source: "legacy-unverified",
      amount: { status: "reported", value: 0.001 },
      unit: { status: "unreported" },
    });
    expect(storage.events).toHaveLength(before.events.length + 1);
    await runtime.close();
    runtime = await fixture(undefined, undefined, path);
    expect(await ledger()).toContainEqual(declaration);
    expect(runtime.generationCostStorage(id)).toEqual(storage);
    runtime.corruptGenerationObservation(id, 1);
    const corrupted = runtime.generationCostStorage(id);
    for (const response of [
      await runtime.request(
        `/api/v2/projects/${source.project.id}/generation-ledger`,
      ),
      await patch({ actualCost: 9 }),
    ]) {
      expect(response.status).toBe(503);
      expect(response.headers.get("Content-Type")).toContain(
        "application/problem+json",
      );
      expect(ProblemDetailsSchema.parse(await response.json()).code).toBe(
        "GENERATION_COST_INTEGRITY_ERROR",
      );
    }
    expect(runtime.generationCostStorage(id)).toEqual(corrupted);
  }, 30_000);

