      const controlledHost = {
        providerRequest: async (
          request: ProviderHttpRequest,
        ): Promise<ProviderHttpResponse> => {
          calls.push(request);
          if (calls.length === 1) {
            entered.resolve();
            await release.promise;
          }
          return kind === "image"
            ? {
                status: 200,
                contentType: "application/json",
                json: { data: [{ b64_json: "Y29udHJvbGxlZC1pbWFnZQ==" }] },
              }
            : {
                status: 200,
                contentType: "audio/mpeg",
                base64: "Y29udHJvbGxlZC1hdWRpbw==",
              };
        },
      } as DesktopHostClient;
