  it("derivation creation receipt failure preserves the original project and preview and commits the target atomically", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-derive-binding-"));
    temporaryDirectories.push(directory);
    const databasePath = join(directory, "runtime.db");
    let runtime = await fixture(undefined, undefined, databasePath);
    const sourceResponse = await runtime.request("/api/v2/projects", {
      method: "POST",
      headers: { "Idempotency-Key": crypto.randomUUID() },
      body: JSON.stringify({
        title: "派生原项目",
        mode: "single_season",
        modeConfig: { mode: "single_season", entryPath: "script" },
      }),
    });
    expect(sourceResponse.status).toBe(201);
    const { project: source } = await sourceResponse.json();
    const previewResponse = await runtime.request(
      `/api/v2/projects/${source.id}/derivations/preview`,
      {
        method: "POST",
        body: JSON.stringify({
          targetMode: "series_longform",
          title: "派生长篇",
        }),
      },
    );
    expect(previewResponse.status).toBe(201);
    const preview = await previewResponse.json();
    const key = crypto.randomUUID();
    const commit = () =>
      runtime.request(`/api/v2/projects/${source.id}/derivations`, {
        method: "POST",
        headers: { "Idempotency-Key": key },
        body: JSON.stringify({ previewId: preview.id }),
      });
    const before = runtime.projectCreationStorage();
    runtime.failProjectCreationReceipts(true);
    expect((await commit()).status).toBe(500);
    expect(runtime.projectCreationStorage()).toEqual(before);
    runtime.failProjectCreationReceipts(false);
    const committed = await commit();
    expect(committed.status, await committed.clone().text()).toBe(201);
    const original = await committed.json();
    expect(original.project.derivedFromProjectId).toBe(source.id);
    const after = runtime.projectCreationStorage();
    expect(after.projects).toHaveLength(2);
    expect(after.derivations).toHaveLength(1);
    expect(after.previews).toHaveLength(0);
    await runtime.close();
    runtime = await fixture(undefined, undefined, databasePath);
    const replay = await commit();
    expect(replay.status).toBe(201);
    expect(replay.headers.get("Idempotency-Replayed")).toBe("true");
    expect(await replay.json()).toEqual(original);
    const crossOperation = await runtime.request("/api/v2/projects", {
      method: "POST",
      headers: { "Idempotency-Key": key },
      body: JSON.stringify({ title: "不能借派生键新建" }),
    });
    expect(crossOperation.status).toBe(409);
    expect(runtime.projectCreationStorage()).toEqual(after);
    for (const path of [
      `/api/v2/projects/${crypto.randomUUID()}/derivations`,
      `/api/v2/projects/${source.id}/derivations`,
    ]) {
      const mismatch = await runtime.request(path, {
        method: "POST",
        headers: { "Idempotency-Key": key },
        body: JSON.stringify({
          previewId: path.includes(source.id)
            ? crypto.randomUUID()
            : preview.id,
        }),
      });
      expect(mismatch.status).toBe(409);
      expect((await mismatch.json()).code).toBe("IDEMPOTENCY_CONFLICT");
    }
    expect(runtime.projectCreationStorage()).toEqual(after);
    runtime.makeLegacyProjectReceipt(key);
    const legacy = runtime.projectCreationStorage();
    const unknown = await commit();
    expect(unknown.status).toBe(409);
    expect((await unknown.json()).code).toBe("IDEMPOTENCY_BINDING_UNKNOWN");
    expect(runtime.projectCreationStorage()).toEqual(legacy);
  });

