  it("reads current Story Bible source state without mutating history, then records explicit conflict and discard exactly once", async () => {
    const runtime = await fixture();
    const create = async (path: string, body: unknown) => {
      const response = await runtime.request(path, {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify(body),
      });
      expect(response.status, await response.clone().text()).toBe(201);
      return await response.json();
    };
    const { project } = (await create("/api/v2/projects", {
      title: "圣经来源核对",
    })) as { project: { id: string } };
    const chapter = (await create("/api/v2/chapters", {
      projectId: project.id,
      title: "作者稿",
      content: "作者最初保存的正文。",
    })) as { id: string; version: number };
    const draft = (await create("/api/v2/story-bible/change-sets", {
      projectId: project.id,
      chapterId: chapter.id,
    })) as StoryBibleChangeSet;
    const history = runtime.storyBibleHistory(draft.id);
    const list = async () => {
      const response = await runtime.request(
        `/api/v2/projects/${project.id}/story-bible/change-sets`,
      );
      expect(response.status).toBe(200);
      return (await response.json()) as StoryBibleChangeSet[];
    };
    expect(await list()).toMatchObject([
      { id: draft.id, status: "draft", sourceState: "current" },
    ]);
    const edit = await runtime.request(`/api/v2/chapters/${chapter.id}`, {
      method: "PATCH",
      body: JSON.stringify({ version: chapter.version, content: "作者新稿。" }),
    });
    expect(edit.status).toBe(200);
    const latestChapter = await edit.json();
    const beforeReads = runtime.domainEvents();
    for (let repeat = 0; repeat < 2; repeat++)
      expect(await list()).toMatchObject([
        {
          id: draft.id,
          status: "draft",
          sourceState: "stale",
          sourceVersion: chapter.version,
          updatedAt: draft.updatedAt,
          preview: draft.preview,
        },
      ]);
    expect(runtime.storyBibleHistory(draft.id)).toEqual(history);
    expect(runtime.domainEvents()).toEqual(beforeReads);
    const memories = async () =>
      await (
        await runtime.request(
          `/api/v2/chapter-memories?projectId=${project.id}`,
        )
      ).json();
    expect(await memories()).toEqual([]);
    const apply = () =>
      runtime.request(`/api/v2/story-bible/change-sets/${draft.id}/apply`, {
        method: "POST",
        body: JSON.stringify({}),
      });
    expect((await apply()).status).toBe(409);
    expect((await apply()).status).toBe(409);
    expect(runtime.storyBibleHistory(draft.id)).toMatchObject({
      status: "stale",
    });
    const conflicts = runtime
      .domainEvents()
      .filter(
        (event) => event.type === "knowledge.story-bible-source-conflicted.v1",
      );
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0]?.payload).toEqual({ id: draft.id, status: "stale" });
    expect(await memories()).toEqual([]);
    const discard = () =>
      runtime.request(`/api/v2/story-bible/change-sets/${draft.id}/status`, {
        method: "PATCH",
        body: JSON.stringify({ status: "discarded" }),
      });
    const discarded = await discard();
    expect(discarded.status).toBe(200);
    const discardedValue = await discarded.json();
    const afterDiscard = runtime.domainEvents();
    expect(discardedValue).toMatchObject({ id: draft.id, status: "discarded" });
    const replay = await discard();
    expect(replay.status).toBe(200);
    expect(await replay.json()).toEqual(discardedValue);
    expect(runtime.domainEvents()).toEqual(afterDiscard);
    expect(
      await (await runtime.request(`/api/v2/chapters/${chapter.id}`)).json(),
    ).toEqual(latestChapter);
  });

