  it("ordinary import rejects foreign scope, changed keys and corrupt owner or parent receipts without recreating content", async () => {
    for (const owner of ["writing", "production"] as const) {
      const runtime = await fixture({
        readGrantedDocument: async () =>
          owner === "writing"
            ? {
                name: "身份.md",
                format: "markdown",
                size: 20,
                content: "# 身份\n\n## 第一章\n\n林晚说信封。",
              }
            : {
                name: "身份.json",
                format: "script-json",
                size: 50,
                content: JSON.stringify({
                  title: "身份",
                  episodes: [
                    {
                      episodeNumber: 1,
                      scenes: [{ title: "车站", content: "林晚拆信。" }],
                    },
                  ],
                }),
              },
      } as unknown as DesktopHostClient);
      const create = async (title: string) =>
        (await runtime
          .request("/api/v2/projects", {
            method: "POST",
            headers: { "Idempotency-Key": crypto.randomUUID() },
            body: JSON.stringify({ title }),
          })
          .then((r) => r.json())) as { project: Project };
      const { project } = await create("原项目");
      const { project: other } = await create("其他项目");
      const source = (await runtime
        .request("/api/v2/source-imports/preview", {
          method: "POST",
          body: JSON.stringify({
            projectId: project.id,
            capabilityToken: crypto.randomUUID(),
          }),
        })
        .then((r) => r.json())) as {
        importId: string;
        preview: import("@dramaip/contracts/workspace").SourceImportPreview;
      };
      const key = crypto.randomUUID();
      const input = {
        projectId: project.id,
        strategy: "append",
        rightsConfirmed: true,
        destructiveConfirmed: false,
        preview: source.preview,
      };
      const send = (id = source.importId, requestKey = key, body = input) =>
        runtime.request(`/api/v2/source-imports/${id}/commit`, {
          method: "POST",
          headers: { "Idempotency-Key": requestKey },
          body: JSON.stringify(body),
        });
      runtime.failOrdinaryImportReceipt("workspace", true);
      expect((await send()).status).toBe(500);
      runtime.failOrdinaryImportReceipt("workspace", false);
      const original = runtime.ordinaryImportStorage();
      for (const rejected of [
        await send(source.importId, crypto.randomUUID()),
        await send(crypto.randomUUID()),
        await send(source.importId, key, { ...input, projectId: other.id }),
        await runtime.request(
          `/api/v2/source-imports/${source.importId}/commit?${new URLSearchParams({ projectId: other.id, requestKey: key })}`,
        ),
        await runtime.request(
          `/api/v2/source-imports/${source.importId}/commit?${new URLSearchParams({ projectId: project.id, requestKey: crypto.randomUUID() })}`,
        ),
      ]) {
        expect(rejected.status).toBe(409);
        expect(await rejected.text()).not.toContain(
          source.preview.chapters[0]?.content ?? "林晚拆信。",
        );
      }
      expect(
        (
          await runtime.request(`/api/v2/source-imports/${source.importId}`, {
            method: "DELETE",
          })
        ).status,
      ).toBe(409);
      expect(runtime.ordinaryImportStorage()).toEqual(original);
      runtime.corruptOrdinaryImport(owner, source.importId);
      const ownerCorrupt = runtime.ordinaryImportStorage();
      expect((await send()).status).toBe(409);
      expect(runtime.ordinaryImportStorage()).toEqual(ownerCorrupt);
      runtime.corruptOrdinaryImport("workspace", source.importId);
      const parentCorrupt = runtime.ordinaryImportStorage();
      expect((await send()).status).toBe(409);
      const read = await runtime.request(
        `/api/v2/source-imports/${source.importId}/commit?${new URLSearchParams({ projectId: project.id, requestKey: key })}`,
      );
      expect(read.status).toBe(409);
      expect(await read.text()).toContain("IDEMPOTENCY_BINDING_UNKNOWN");
      expect(runtime.ordinaryImportStorage()).toEqual(parentCorrupt);
    }
  });

  it("ordinary import extraction refuses a changed chapter before adopting any other selected candidate", async () => {
    const runtime = await fixture({
      readGrantedDocument: async () => ({
        name: "摘要.md",
        format: "markdown",
        size: 50,
        content:
          "# 原稿\n\n## 第一章\n\n林晚说信封。\n\n## 第二章\n\n电话已经断了。",
      }),
    } as unknown as DesktopHostClient);
    const { project } = (await runtime
      .request("/api/v2/projects", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({ title: "摘要原身份" }),
      })
      .then((r) => r.json())) as { project: Project };
    const source = (await runtime
      .request("/api/v2/source-imports/preview", {
        method: "POST",
        body: JSON.stringify({
          projectId: project.id,
          capabilityToken: crypto.randomUUID(),
        }),
      })
      .then((r) => r.json())) as {
      importId: string;
      preview: import("@dramaip/contracts/workspace").SourceImportPreview;
    };
    const result = (await runtime
      .request(`/api/v2/source-imports/${source.importId}/commit`, {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          projectId: project.id,
          strategy: "append",
          rightsConfirmed: true,
          destructiveConfirmed: false,
          preview: source.preview,
        }),
      })
      .then((r) =>
        r.json(),
      )) as import("@dramaip/contracts/workspace").SourceImportCommitResult;
    const extraction = result.extractionChangeSet!;
    const summary = extraction.candidates.find(
      (candidate) => candidate.type === "chapter-summary",
    )!;
    const character = extraction.candidates.find(
      (candidate) => candidate.type === "character",
    )!;
    const ref = summary.sourceRefs[0]!;
    const edit = await runtime.request(`/api/v2/chapters/${ref.chapterId}`, {
      method: "PATCH",
      body: JSON.stringify({
        version: ref.sourceVersion,
        content: "后来人工修订，原摘要不得覆盖。",
      }),
    });
    expect(edit.status).toBe(200);
    const original = runtime.ordinaryImportStorage();
    const rejected = await runtime.request(
      `/api/v2/import-extractions/change-sets/${extraction.id}/adopt`,
      {
        method: "POST",
        body: JSON.stringify({ candidateIds: [character.id, summary.id] }),
      },
    );
    expect(rejected.status).toBe(409);
    expect(await rejected.text()).toContain("SOURCE_CHANGED");
    expect(runtime.ordinaryImportStorage()).toEqual(original);
    await expect(
      runtime
        .request(`/api/v2/characters?projectId=${project.id}`)
        .then((r) => r.json()),
    ).resolves.toEqual([]);
  });

  it("ordinary script recovery after restart preserves a later project version and does not overwrite its adaptation head", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-ordinary-cas-"));
    temporaryDirectories.push(directory);
    const databasePath = join(directory, "ordinary.sqlite");
    let runtime = await fixture(
      {
        readGrantedDocument: async () => ({
          name: "剧本.json",
          format: "script-json",
          size: 50,
          content: JSON.stringify({
            title: "剧本",
            episodes: [
              {
                episodeNumber: 1,
                scenes: [{ title: "车站", content: "林晚拆信。" }],
              },
            ],
          }),
        }),
      } as unknown as DesktopHostClient,
      undefined,
      databasePath,
    );
    const { project } = (await runtime
      .request("/api/v2/projects", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({ title: "原项目" }),
      })
      .then((r) => r.json())) as { project: Project };
    const source = (await runtime
      .request("/api/v2/source-imports/preview", {
        method: "POST",
        body: JSON.stringify({
          projectId: project.id,
          capabilityToken: crypto.randomUUID(),
        }),
      })
      .then((r) => r.json())) as {
      importId: string;
      preview: import("@dramaip/contracts/workspace").SourceImportPreview;
    };
    const key = crypto.randomUUID();
    const input = {
      projectId: project.id,
      strategy: "append",
      rightsConfirmed: true,
      destructiveConfirmed: false,
      preview: source.preview,
    };
    const send = () =>
      runtime.request(`/api/v2/source-imports/${source.importId}/commit`, {
        method: "POST",
        headers: { "Idempotency-Key": key },
        body: JSON.stringify(input),
      });
    runtime.failOrdinaryImportReceipt("workspace", true);
    expect((await send()).status).toBe(500);
    runtime.failOrdinaryImportReceipt("workspace", false);
    const changed = await runtime.request(`/api/v2/projects/${project.id}`, {
      method: "PATCH",
      headers: { "If-Match": `"${project.version}"` },
      body: JSON.stringify({ title: "后来明确修订", version: project.version }),
    });
    expect(changed.status, await changed.clone().text()).toBe(200);
    const later = await changed.json();
    const original = runtime.ordinaryImportStorage();
    await runtime.close();
    runtime = await fixture(undefined, undefined, databasePath);
    expect((await send()).status).toBe(409);
    expect(runtime.ordinaryImportStorage()).toEqual(original);
    await expect(
      runtime.request(`/api/v2/projects/${project.id}`).then((r) => r.json()),
    ).resolves.toEqual(later);
    const pending = await runtime.request(
      `/api/v2/source-imports/${source.importId}/commit?${new URLSearchParams({ projectId: project.id, requestKey: key })}`,
    );
    expect(pending.status).toBe(200);
    await expect(pending.json()).resolves.toMatchObject({
      state: "pending",
      input,
    });
    expect(runtime.ordinaryImportStorage()).toEqual(original);
  });

