  it("source lifecycle explicitly withdraws and replaces node, relationship and cognition identities without rewriting original adoptions, receipts or snapshots", async () => {
    const runtime = await fixture(undefined, undefined, ":memory:", true);
    const { project, input } = await savedScript(runtime);
    const nodeCandidate = await declarationCreate(runtime, project.id, input);
    const oldNodeResponse = await declarationAdopt(runtime, nodeCandidate);
    expect(oldNodeResponse.status).toBe(200);
    const oldNode = (await oldNodeResponse.json()) as Declaration;
    const from = await assertionNode(runtime, project.id, "character"),
      to = await assertionNode(runtime, project.id, "secret");
    const oldAssertions: Assertion[] = [];
    for (const body of [
      relationInput(input.sources, from, to),
      cognitionInput(input.sources, from, to),
    ]) {
      const candidate = await assertionCreate(runtime, project.id, body);
      const response = await assertionAdopt(runtime, candidate);
      expect(response.status).toBe(200);
      oldAssertions.push((await response.json()) as Assertion);
    }
    const twin = await (
      await declarationPost(
        runtime,
        `/api/v2/projects/${project.id}/ip-twin`,
        {},
      )
    ).json();
    const frozenBefore =
      runtime.declarationStorage().knowledge_ip_twin_snapshots;
    const manuscript = runtime.screenplaySourceStorage(),
      calls = prompts.length;
    for (const old of [oldNode, ...oldAssertions]) {
      const isNode = "adoptedNode" in old;
      const base = isNode
        ? `${declarationPath(project.id)}/${old.id}`
        : assertionPath(project.id, old.id);
      expect(old.lifecycle).toMatchObject({ state: "active", version: 0 });
      const oldBinding = isNode
        ? (old as Declaration).adoptedNode
        : (old as Assertion).adoptedRecord;
      const withdrawInput = {
        lifecycleVersion: old.lifecycle!.version,
        record: old.lifecycle!.record,
        reason: "明确撤回旧解释，保留真实历史",
        confirmedRetirementReview: true,
      };
      const key = crypto.randomUUID(),
        headers = { "If-Match": old.etag, "Idempotency-Key": key };
      const response = await declarationPost(
        runtime,
        `${base}/withdraw`,
        withdrawInput,
        headers,
      );
      expect(response.status, await response.clone().text()).toBe(200);
      const withdrawn = (await response.json()) as Declaration | Assertion;
      expect(withdrawn).toMatchObject({
        id: old.id,
        version: old.version,
        status: "adopted",
        basis: old.basis,
        input: old.input,
        lifecycle: {
          state: "withdrawn",
          version: 1,
          record: { id: oldBinding!.id, version: oldBinding!.version + 1 },
        },
      });
      const replacement = isNode
        ? await declarationCreate(runtime, project.id, {
            ...input,
            statement: "新独立审阅节点解释",
          })
        : await assertionCreate(runtime, project.id, {
            ...(old as Assertion).input,
            statement: "新独立审阅关系或认知解释",
          });
      const replaceInput = {
        lifecycleVersion: withdrawn.lifecycle!.version,
        record: withdrawn.lifecycle!.record,
        reason: "明确采用此新候选，不自动换源",
        confirmedRetirementReview: true,
        replacement: {
          id: replacement.id,
          etag: replacement.etag,
          sourceFingerprint: replacement.basis.fingerprint,
          confirmedSourceReview: true,
          confirmedInterpretationReview: true,
        },
      };
      const replacedResponse = await declarationPost(
        runtime,
        `${base}/replace`,
        replaceInput,
        { "If-Match": withdrawn.etag },
      );
      expect(
        replacedResponse.status,
        await replacedResponse.clone().text(),
      ).toBe(200);
      const replaced = (await replacedResponse.json()) as
        Declaration | Assertion;
      expect(replaced.lifecycle).toMatchObject({
        state: "replaced",
        version: 2,
        replacementId: replacement.id,
      });
      expect(replaced.lifecycle!.transitions.map((t) => t.action)).toEqual([
        "withdraw",
        "replace",
      ]);
      expect(replaced.basis).toEqual(old.basis);
      expect(replaced.input).toEqual(old.input);
      const readNew = isNode
        ? await declarationRead(runtime, replacement as Declaration)
        : await assertionRead(runtime, replacement as Assertion);
      expect(readNew.status).toBe("adopted");
      expect(readNew.lifecycle!.state).toBe("active");
      expect(readNew.lifecycle!.record.id).not.toBe(oldBinding!.id);
      const stable = runtime.declarationStorage(),
        events = runtime.domainEvents();
      const replay = await declarationPost(
        runtime,
        `${base}/withdraw`,
        withdrawInput,
        headers,
      );
      expect(replay.status).toBe(200);
      expect((await replay.json()).lifecycle.state).toBe("replaced");
      expect(runtime.declarationStorage()).toEqual(stable);
      expect(runtime.domainEvents()).toEqual(events);
    }
    const withdrawnLineage = await m4ExpectStoredKnowledgeLineage(
      runtime,
      project.id,
    );
    expect(withdrawnLineage.transitions).toHaveLength(6);
    expect(
      withdrawnLineage.transitions.filter((item) => item.version === 1),
    ).toHaveLength(3);
    expect(
      withdrawnLineage.transitions.filter((item) => item.version === 2),
    ).toHaveLength(3);
    expect(runtime.declarationStorage().knowledge_ip_twin_snapshots).toEqual(
      frozenBefore,
    );
    const currentTwin = await (
      await declarationPost(
        runtime,
        `/api/v2/projects/${project.id}/ip-twin`,
        {},
      )
    ).json();
    expect(
      currentTwin.nodes.some(
        (n: { id: string }) => n.id === oldNode.adoptedNode!.id,
      ),
    ).toBe(false);
    for (const old of oldAssertions)
      expect(
        [...currentTwin.edges, ...currentTwin.audienceStates].some(
          (n: { id: string }) => n.id === old.adoptedRecord!.id,
        ),
      ).toBe(false);
    const oldTwin = await (
      await runtime.request(
        `/api/v2/projects/${project.id}/ip-twins/${twin.id}`,
      )
    ).json();
    expect(oldTwin).toEqual({ ...twin, stale: true });
    expect(runtime.screenplaySourceStorage()).toEqual(manuscript);
    expect(prompts).toHaveLength(calls);
    const events = JSON.stringify(
      runtime
        .domainEvents()
        .filter(
          (e) => e.type.includes("withdrawn") || e.type.includes("replaced"),
        ),
    );
    expect(events).not.toContain("PRIVATE");
    expect(events).not.toContain("明确撤回");
  });

