  it("actual workflow saves each reported usage with strict owner events across SQLite restart, including a failed run, without summing or leaking prompts", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-workflow-usage-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let failed = false;
    const sent: string[] = [];
    const engine = host(
      (prompt) => {
        sent.push(prompt);
        if (failed)
          throw new Error("controlled engine interruption after usage");
        return prompt.includes("审阅候选与冻结")
          ? JSON.stringify({ issues: [] })
          : JSON.stringify(explicitPlanningOutput("characters"));
      },
      [
        {
          measurementScope: "response-increment",
          inputTokens: 0,
          outputTokens: 12,
        },
        {
          measurementScope: "session-total",
          inputTokens: 100,
          outputTokens: 40,
          cachedTokens: 0,
        },
      ],
    );
    let runtime = await fixture(undefined, engine, path, true);
    const { project, chapter } = await seed(runtime);
    const initial = await start(runtime, {
      projectId: project.id,
      operation: "characters",
      wordGoal: undefined,
      narrativePlanningRequest: explicitOriginalPlanning(chapter),
    });
    const ready = await until(runtime, initial.id, [
      "awaiting-review",
      "failed",
    ]);
    expect(ready.stage, ready.error).toBe("awaiting-review");
    const read = async (runId: string) => {
      const response = await runtime.request(
        `/api/v2/agent-runs/${runId}/usage-observations?projectId=${project.id}`,
      );
      expect(response.status, await response.clone().text()).toBe(200);
      return response.json();
    };
    const original = await read(ready.runId!);
    expect(original).toMatchObject({
      observationCount: 2,
      coverage: "partial-or-unknown",
      billingStatus: "unknown",
      items: [
        {
          cursor: 2,
          measurementScope: "session-total",
          inputTokens: { status: "reported", value: 100 },
        },
        {
          cursor: 1,
          measurementScope: "response-increment",
          inputTokens: { status: "reported", value: 0 },
          cachedTokens: { status: "unreported" },
        },
      ],
    });
    expect(JSON.stringify(original)).not.toContain("原正文保留");
    const calls = sent.length;
    await runtime.close();
    runtime = await fixture(undefined, engine, path, true);
    expect(await read(ready.runId!)).toEqual(original);
    expect(sent.length).toBe(calls);
    expect(
      (
        await runtime.request(
          `/api/v2/agent-runs/${ready.runId}/usage-observations?projectId=other-project`,
        )
      ).status,
    ).toBe(404);
    failed = true;
    const next = await start(runtime, {
      projectId: project.id,
      operation: "characters",
      wordGoal: undefined,
      narrativePlanningRequest: explicitOriginalPlanning(chapter),
    });
    const interrupted = await until(runtime, next.id, ["failed"]);
    expect(await read(interrupted.runId!)).toMatchObject({
      observationCount: 2,
      items: [{ cursor: 2 }, { cursor: 1 }],
    });
    expect(await read(ready.runId!)).toEqual(original);
    expect(sent.length).toBe(calls + 1);
  });

