      expect(restored.domainEvents()).toEqual(eventsBeforeConflict);
      expect(restored.planningStorage()).toEqual(storageBeforeConflict);
      restored.failSourceConflictEvents(false);
      expect((await commitCreation(restored, ready.previewId!)).status).toBe(
        409,
      );
      expect((await commitCreation(restored, ready.previewId!)).status).toBe(
        409,
      );
      const exactConflicts = restored
        .domainEvents()
