      const originalRejected = await restored
        .request(`/api/v2/workflows/creation/${ready.id}`)
        .then((response) => response.json());
      const historical = await outcomeSummary(restored, project.id),
        persisted = restored.planningStorage();
      const originalCalls = sent.length;
