    expect(commit.status, await commit.clone().text()).toBe(200);
    const adopted = await until(runtime, planned.id, ["applied", "failed"]);
    expect(adopted.stage, adopted.error).toBe("applied");
    const materials = (await runtime
      .request(`/api/v2/characters?projectId=${project.id}`)
      .then((r) => r.json())) as Array<{ id: string; version: number }>;
