  it("M4 project lineage exports every actual workflow past the 25-item page boundary and excludes another project without adopting any candidate or making new model calls", async () => {
    const sent: string[] = [],
      engine = host((prompt) => {
        sent.push(prompt);
        return JSON.stringify(
          prompt.includes("审阅候选与冻结") ? { issues: [] } : intentOutput(),
        );
      });
    const runtime = await fixture(undefined, engine, ":memory:", true),
      { project } = await seed(runtime),
      catalog = await intentCatalog(runtime, project.id);
    const initials = [];
    for (let index = 0; index < 27; index++)
      initials.push(
        await startAiIntent(runtime, project.id, {
          projectVersion: catalog.projectVersion,
          sources: [],
        }),
      );
    const ready = await Promise.all(
      initials.map((value) =>
        until(runtime, value.id, ["awaiting-review", "failed"]),
      ),
    );
    for (const value of ready)
      expect(value.stage, value.error).toBe("awaiting-review");
    const other = await seed(runtime),
      otherCatalog = await intentCatalog(runtime, other.project.id),
      foreign = await until(
        runtime,
        (
          await startAiIntent(runtime, other.project.id, {
            projectVersion: otherCatalog.projectVersion,
            sources: [],
          })
        ).id,
        ["awaiting-review", "failed"],
      );
    expect(foreign.stage, foreign.error).toBe("awaiting-review");
    const first = runtime.readProjectLineage(project.id) as {
      items: { id: string }[];
      nextCursor?: string;
    };
    expect(first.items).toHaveLength(25);
    expect(first.nextCursor).toBeDefined();
    const before = runtime.allocationCounts(),
      calls = sent.length;
    const response = await runtime.request(
      `/api/v2/exports/projects/${project.id}/json`,
    );
    expect(response.status, await response.clone().text()).toBe(200);
    const items = JSON.parse(
      ((await response.json()) as { content: string }).content,
    ).lineage.workflows.items as Array<{
      id: string;
      projectId: string;
      stage: string;
    }>;
    expect(items).toHaveLength(27);
    expect(new Set(items.map((item) => item.id)).size).toBe(27);
    expect(items.map((item) => item.id).sort()).toEqual(
      ready.map((value) => value.id).sort(),
    );
    expect(items.some((item) => item.id === foreign.id)).toBe(false);
    for (const item of items) {
      expect(item.projectId).toBe(project.id);
      expect(item.stage).toBe("awaiting-review");
    }
    expect(runtime.allocationCounts()).toEqual(before);
    expect(sent).toHaveLength(calls);
    for (const value of ready)
      expect(
        await runtime
          .request(`/api/v2/workflows/creation/${value.id}`)
          .then((r) => r.json()),
      ).toEqual(value);
  }, 90000);

  it("M4 imported lineage archives survive SQLite and A-B-C package chains as readonly foreign claims without native workflow or intent activation", async () => {
    const origin = await fixture(undefined, undefined, ":memory:", true),
      { project, chapter } = await seed(origin);
    const read = async (runtime: Fixture, id: string) => {
      const response = await runtime.request(
        `/api/v2/exports/projects/${id}/json`,
      );
      expect(response.status, await response.clone().text()).toBe(200);
      return JSON.parse(
        ((await response.json()) as { content: string }).content,
      );
    };
    const packet = await read(origin, project.id),
      original = structuredClone(packet),
      dir = await mkdtemp(join(tmpdir(), "dramaip-m4-import-archive-test-")),
      databasePath = join(dir, "runtime.sqlite");
    let importText = JSON.stringify(packet),
      runtime = await fixture(
        {
          readGrantedText: async () => ({
            name: "controlled.json",
            content: importText,
          }),
        } as unknown as DesktopHostClient,
        undefined,
        databasePath,
        true,
      );
    const importOne = async () => {
      const response = await runtime.request(
        "/api/v2/project-packages/preview",
        {
          method: "POST",
          body: JSON.stringify({ capabilityToken: crypto.randomUUID() }),
        },
      );
      expect(response.status, await response.clone().text()).toBe(201);
      const preview = (await response.json()) as { id: string };
      const committed = await runtime.request(
        `/api/v2/project-packages/${preview.id}/commit`,
        { method: "POST", body: "{}" },
      );
      expect(committed.status, await committed.clone().text()).toBe(201);
      return ((await committed.json()) as { project: { id: string } }).project;
    };
    try {
      const second = await importOne(),
        exported = await read(runtime, second.id);
      expect(exported.importedLineageArchives).toHaveLength(1);
      const claim = exported.importedLineageArchives[0];
      expect(claim).toMatchObject({
        format: "project-package-imported-lineage-v1",
        sourcePackageSchemaVersion: 5,
        sourceExportedAt: packet.exportedAt,
        trust: "imported-claim-not-local-workflow-or-authority",
        lineage: packet.lineage,
        fingerprint: { format: "derived-canonical-imported-claim-v1" },
      });
      expect(exported.lineage.sourceProject.id).toBe(second.id);
      expect(exported.lineage.workflows).toEqual({
        state: "available",
        items: [],
      });
      expect(claim.lineage.sourceProject.id).toBe(project.id);
      expect(exported.chapters[0]).toMatchObject({
        version: 0,
        content: "原正文保留。",
      });
      expect(exported.chapters[0].id).not.toBe(chapter.id);
      const before = runtime.allocationCounts(),
        events = runtime.domainEvents();
      expect((await read(runtime, second.id)).importedLineageArchives).toEqual([
        claim,
      ]);
      expect(runtime.allocationCounts()).toEqual(before);
      expect(runtime.domainEvents()).toEqual(events);
      await runtime.close();
      runtime = await fixture(
        {
          readGrantedText: async () => ({
            name: "controlled.json",
            content: importText,
          }),
        } as unknown as DesktopHostClient,
        undefined,
        databasePath,
        true,
      );
      expect((await read(runtime, second.id)).importedLineageArchives).toEqual([
        claim,
      ]);
      importText = JSON.stringify(exported);
      const third = await importOne(),
        thirdPackage = await read(runtime, third.id);
      expect(thirdPackage.importedLineageArchives).toHaveLength(2);
      expect(thirdPackage.importedLineageArchives).toContainEqual(claim);
      expect(
        thirdPackage.importedLineageArchives.find(
          (item: typeof claim) => item.lineage.sourceProject.id === second.id,
        ).lineage,
      ).toEqual(exported.lineage);
      expect(thirdPackage.lineage.workflows).toEqual({
        state: "available",
        items: [],
      });
      expect(
        await runtime
          .request(`/api/v2/workflows/creation?projectId=${third.id}`)
          .then((response) => response.json()),
      ).toEqual({ items: [] });
      expect(
        await runtime
          .request(`/api/v2/projects/${third.id}/author-intent`)
          .then((response) => response.json()),
      ).not.toHaveProperty("current");
      expect(packet).toEqual(original);
    } finally {
      await runtime.close();
      await rm(dir, { recursive: true, force: true });
    }
  }, 45000);

  it("M4 imported lineage archive integrity rejects foreign private additions, checksum changes, duplicates and legacy claims, and rolls project/archive/events back together", async () => {
    const origin = await fixture(undefined, undefined, ":memory:", true),
      { project } = await seed(origin),
      document = (await origin
        .request(`/api/v2/exports/projects/${project.id}/json`)
        .then((response) => response.json())) as { content: string };
    let importText = document.content;
    const runtime = await fixture(
      {
        readGrantedText: async () => ({
          name: "controlled.json",
          content: importText,
        }),
      } as unknown as DesktopHostClient,
      undefined,
      ":memory:",
      true,
    );
    const preview = () =>
      runtime.request("/api/v2/project-packages/preview", {
        method: "POST",
        body: JSON.stringify({ capabilityToken: crypto.randomUUID() }),
      });
    const response = await preview();
    expect(response.status).toBe(201);
    const id = ((await response.json()) as { id: string }).id;
    const before = runtime.projectCreationStorage();
    runtime.failImportedLineage(true);
    const failed = await runtime.request(
      `/api/v2/project-packages/${id}/commit`,
      { method: "POST", body: "{}" },
    );
    expect(failed.status).toBe(409);
    expect(failed.headers.get("content-type")).toContain(
      "application/problem+json",
    );
    expect(await failed.text()).not.toContain("PRIVATE");
    expect(runtime.projectCreationStorage()).toEqual(before);
    expect(runtime.importedLineageStorage()).toEqual([]);
    runtime.failImportedLineage(false);
    const committed = await runtime.request(
      `/api/v2/project-packages/${id}/commit`,
      { method: "POST", body: "{}" },
    );
    expect(committed.status, await committed.clone().text()).toBe(201);
    const created = ((await committed.json()) as { project: { id: string } })
      .project;
    const exported = JSON.parse(
        (
          (await runtime
            .request(`/api/v2/exports/projects/${created.id}/json`)
            .then((response) => response.json())) as { content: string }
        ).content,
      ),
      archive = exported.importedLineageArchives[0];
    for (const mutation of [
      {
        ...exported,
        importedLineageArchives: [
          {
            ...archive,
            lineage: {
              ...archive.lineage,
              preparedPrompt: "PRIVATE forbidden",
            },
          },
        ],
      },
      {
        ...exported,
        importedLineageArchives: [
          { ...archive, sourceExportedAt: "2020-01-01T00:00:00.000Z" },
        ],
      },
      { ...exported, importedLineageArchives: [archive, archive] },
      { ...exported, schemaVersion: 4, lineage: undefined },
    ]) {
      importText = JSON.stringify(mutation);
      const bad = await preview();
      expect(bad.status, await bad.clone().text()).toBe(400);
      expect(await bad.text()).not.toContain("PRIVATE forbidden");
    }
    const originalRows = runtime.importedLineageStorage(),
      allocations = runtime.allocationCounts(),
      events = runtime.domainEvents();
    runtime.corruptImportedLineage(created.id);
    const rejected = await runtime.request(
      `/api/v2/exports/projects/${created.id}/json`,
    );
    expect(rejected.status).toBe(409);
    expect(await rejected.text()).not.toContain("PRIVATE corrupt");
    expect(runtime.allocationCounts()).toEqual(allocations);
    expect(runtime.domainEvents()).toEqual(events);
    expect(originalRows).toHaveLength(1);
  }, 45000);

