  it("M4 project lineage refuses unsafe original identities, foreign or repeated owner pages and owner outages with a safe structured error, preserves legacy absence and original records", async () => {
    const sent: string[] = [],
      engine = host((prompt) => {
        sent.push(prompt);
        return JSON.stringify(
          prompt.includes("审阅候选与冻结") ? { issues: [] } : intentOutput(),
        );
      });
    const runtime = await fixture(undefined, engine, ":memory:", true),
      { project } = await seed(runtime),
      catalog = await intentCatalog(runtime, project.id);
    const ready = await until(
      runtime,
      (
        await startAiIntent(runtime, project.id, {
          projectVersion: catalog.projectVersion,
          sources: [],
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect(ready.stage, ready.error).toBe("awaiting-review");
    const read = () =>
      runtime.request(`/api/v2/exports/projects/${project.id}/json`);
    const first = await read();
    expect(first.status, await first.clone().text()).toBe(200);
    const packet = JSON.parse(
      ((await first.json()) as { content: string }).content,
    );
    expect(
      packet.lineage.workflows.items.map((item: { id: string }) => item.id),
    ).toContain(ready.id);
    const before = runtime.allocationCounts(),
      events = runtime.domainEvents(),
      calls = sent.length;
    const refuse = async () => {
      const response = await read();
      expect(response.status).toBe(409);
      expect(response.headers.get("Content-Type")).toContain(
        "application/problem+json",
      );
      const problem = await response.json();
      expect(ProblemDetailsSchema.safeParse(problem).success).toBe(true);
      expect(problem.code).toBe("CAPABILITY_UNAVAILABLE");
      expect(problem.detail).toContain("谱系暂不可完整核对");
      const rendered = JSON.stringify(problem);
      for (const marker of [
        "PRIVATE",
        "UNSAFE_PATH_MARKER",
        "value_json",
        "sourceVersions",
        "/synthetic/private",
      ])
        expect(rendered).not.toContain(marker);
      expect(runtime.allocationCounts()).toEqual(before);
      expect(runtime.domainEvents()).toEqual(events);
      expect(sent).toHaveLength(calls);
    };
    for (const replacement of [
      () => {
        throw new Error("PRIVATE /synthetic/private/owner database failure");
      },
      (raw: unknown) => {
        const page = raw as { items: Record<string, unknown>[] };
        return {
          ...page,
          items: page.items.map((item) => ({
            ...item,
            projectId: crypto.randomUUID(),
          })),
        };
      },
      (raw: unknown) => {
        const page = raw as { items: Record<string, unknown>[] };
        return {
          ...page,
          items: page.items.map((item) => ({
            ...item,
            authorIntent: { state: "none", projectId: crypto.randomUUID() },
          })),
        };
      },
      (raw: unknown) => {
        const page = raw as { items: Record<string, unknown>[] };
        return { items: [...page.items, ...page.items] };
      },
      () => ({ items: [], nextCursor: "PRIVATE invalid infinite page" }),
      (raw: unknown) => ({
        ...(raw as object),
        nextCursor: `${ready.createdAt}|${ready.id}`,
      }),
    ]) {
      const restore = runtime.replaceProjectLineage(replacement);
      try {
        await refuse();
      } finally {
        restore();
      }
    }
    for (const fieldPath of [
      "/Volumes/private/UNSAFE_PATH_MARKER",
      "/writing-resources/characters/../../UNSAFE_PATH_MARKER",
      "/writing-resources/characters/%2FPRIVATE",
      "/writing-resources/characters/file:PRIVATE",
      "/writing-resources/characters/PRIVATE\u0000",
      "/writing-resources/characters/PRIVATE\u0085",
    ]) {
      const restore = runtime.replaceProjectLineage((raw: unknown) => {
        const page = raw as { items: Record<string, unknown>[] };
        return {
          ...page,
          items: page.items.map((item) => ({
            ...item,
            contextEntries: [{ included: true, fieldPath }],
          })),
        };
      });
      try {
        await refuse();
      } finally {
        restore();
      }
    }
    // Agent-context's intent/selection selectors are permitted identities, not
    // exported values or a claim this AI intent receipt used those selectors.
    expect(
      CreationProjectLineageReceiptSchema.safeParse({
        ...packet.lineage.workflows.items[0],
        contextEntries: [
          {
            included: true,
            fieldPath: "/intent",
            sourceId: "run-intent",
            sourceVersion: 0,
          },
          {
            included: true,
            fieldPath: "/selection",
            sourceId: project.id,
            sourceVersion: 0,
          },
        ],
      }).success,
    ).toBe(true);
    const unsafe = {
      ...ready,
      sources: [
        ...ready.sources,
        {
          kind: "chapter",
          id: "/synthetic/private/UNSAFE_PATH_MARKER",
          version: 0,
        },
      ],
    };
    runtime.rewriteLineageWorkflow(ready.id, unsafe);
    try {
      await refuse();
      expect(
        await runtime
          .request(`/api/v2/workflows/creation/${ready.id}`)
          .then((r) => r.json()),
      ).toEqual(unsafe);
    } finally {
      runtime.rewriteLineageWorkflow(ready.id, ready);
    }
    const legacy = { ...ready } as Record<string, unknown>;
    delete legacy.creationRequestReceipt;
    delete legacy.sourceContextIntegrity;
    delete legacy.contextEntries;
    runtime.rewriteLineageWorkflow(ready.id, legacy);
    try {
      const response = await read();
      expect(response.status, await response.clone().text()).toBe(200);
      const original = JSON.parse(
        ((await response.json()) as { content: string }).content,
      ).lineage.workflows.items.find(
        (item: { id: string }) => item.id === ready.id,
      );
      expect(original).not.toHaveProperty("requestHash");
      expect(original).not.toHaveProperty("sourceContextIntegrity");
      expect(original).not.toHaveProperty("contextEntries");
    } finally {
      runtime.rewriteLineageWorkflow(ready.id, ready);
    }
    const final = await read();
    expect(final.status).toBe(200);
    expect(
      JSON.parse(((await final.json()) as { content: string }).content).lineage,
    ).toEqual(packet.lineage);
    expect(runtime.allocationCounts()).toEqual(before);
    expect(runtime.domainEvents()).toEqual(events);
    expect(sent).toHaveLength(calls);
  }, 45000);

