    const added = await runtime.request("/api/v2/chapters", {
      method: "POST",
      body: JSON.stringify({
        projectId: project.id,
        title: "第二章明确选择",
        content: "PRIVATE 第二章作者原稿。",
      }),
    });
    const second = (await added.json()) as { id: string; version: number };
    const catalog = await intentCatalog(runtime, project.id);
    const request = {
      projectVersion: project.version,
      sources: [
        catalog.items.find((item) => item.source.id === second.id)!.source,
      ],
    };
    const workflow = await until(
      runtime,
      (await startAiIntent(runtime, project.id, request)).id,
      ["awaiting-review", "failed"],
    );
    expect(workflow.stage, workflow.error).toBe("awaiting-review");
    const read = async () =>
      (await (
        await runtime.request(
          `/api/v2/author-intents/${workflow.authorIntentId}`,
        )
      ).json()) as AuthorIntent;
    const patch = (id: string, version: number, content: string) =>
      runtime.request(`/api/v2/chapters/${id}`, {
        method: "PATCH",
        headers: { "If-Match": `"${version}"` },
        body: JSON.stringify({ version, content }),
      });
    expect(
      (await patch(chapter.id, chapter.version, "未选第一章只改作者原稿"))
        .status,
    ).toBe(200);
    expect((await read()).sourceState).toBe("current");
    expect(
      (await patch(second.id, second.version, "选定章节由作者明确改写")).status,
    ).toBe(200);
    expect((await read()).sourceState).toBe("stale");
    await runtime.close();
    runtime = await fixture(undefined, engine, database);
    const candidate = await read();
    expect(candidate).toMatchObject({
      id: workflow.authorIntentId,
      sourceState: "stale",
      status: "pending",
    });
