    expect(runtime.domainEvents()).toEqual(events);
    expect(
      await (
        await runtime.request(`/api/v2/projects/${project.id}/chapters`)
      ).json(),
    ).toEqual(chapters);
    expect(prompts).toHaveLength(0);
