    let runtime = await fixture(undefined, engine, databasePath);
    const { project, chapter: first } = await seed(runtime);
    const add = async (title: string, content: string) =>
      (await (
        await runtime.request("/api/v2/chapters", {
          method: "POST",
          body: JSON.stringify({ projectId: project.id, title, content }),
        })
      ).json()) as { id: string; version: number };
    const empty = await add("空章", ""),
      second = await add("第二章", "第二章归还旧书。");
    const memory = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "chapter-memory",
          targetId: first.id,
          baseVersion: first.version,
        })
      ).id,
      ["awaiting-review"],
    );
    expect((await commitCreation(runtime, memory.previewId!)).status).toBe(200);
    firstSummary = (
      (await (
        await runtime.request(
          `/api/v2/projects/${project.id}/narrative-context-index/chapters/${first.id}`,
        )
      ).json()) as NarrativeIndexDetail
    ).summaries[0]!;
    const volumeResponse = await runtime.request(
      `/api/v2/projects/${project.id}/volumes`,
      {
        method: "POST",
        body: JSON.stringify({ projectId: project.id, title: "第一卷" }),
      },
    );
    expect(volumeResponse.status, await volumeResponse.clone().text()).toBe(
      201,
    );
    const volume = (await volumeResponse.json()) as { id: string };
    // Volume membership is an authoritative Writing update, not inferred from chapter numbers.
    for (const chapter of [first, empty]) {
      const current = await (
        await runtime.request(`/api/v2/chapters/${chapter.id}`)
      ).json();
      const moved = await runtime.request(`/api/v2/chapters/${chapter.id}`, {
        method: "PATCH",
        headers: { "If-Match": `"${current.version}"` },
        body: JSON.stringify({ version: current.version, volumeId: volume.id }),
      });
      expect(moved.status, await moved.clone().text()).toBe(200);
    }
    // Moving bumps chapter versions: explicitly regenerate the current adopted summary.
