  it("explicit novel context inherits original privacy for summaries and fragments, rejects unverified or over-budget sources before any task or engine call", async () => {
    let calls = 0;
    const runtime = await fixture(
      undefined,
      host((prompt) => {
        calls++;
        return prompt.includes("审阅候选与冻结")
          ? JSON.stringify({ issues: [] })
          : JSON.stringify({
              title: "摘要",
              content: "保留原稿",
              items: [
                {
                  ref: "m",
                  kind: "chapter-memories",
                  title: "原稿",
                  data: { evidence: "原正文保留。", 章节摘要: "保留原稿" },
                },
              ],
            });
      }),
    );
    const { project, chapter: first } = await seed(runtime);
    const memory = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "chapter-memory",
          targetId: first.id,
          baseVersion: first.version,
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect((await commitCreation(runtime, memory.previewId!)).status).toBe(200);
    await until(runtime, memory.id, ["applied"]);
    const huge = await addNarrativeChapter(
      runtime,
      project.id,
      "长篇正文",
      "长篇正文".repeat(80000),
    );
    const target = await addNarrativeChapter(runtime, project.id, "当前章", "");
    const detail = (await (
      await runtime.request(
        `/api/v2/projects/${project.id}/narrative-context-index/chapters/${first.id}`,
      )
    ).json()) as NarrativeIndexDetail;
    const summary = detail.summaries[0]!,
      paragraph = detail.paragraphs[0]!;
    const policy = await runtime.request(
      `/api/v2/projects/${project.id}/agent-context-policies`,
      {
        method: "PUT",
        headers: { "If-Match": '"0"' },
        body: JSON.stringify({
          version: 0,
          policies: [
            { fieldPath: `/chapters/${first.id}`, mode: "never" },
            { fieldPath: `/knowledge/${summary.id}`, mode: "always" },
            {
              fieldPath: `/chapters/${first.id}/paragraphs/${encodeURIComponent(paragraph.id)}`,
              mode: "always",
            },
          ],
        }),
      },
    );
    expect(policy.status).toBe(200);
    const before = await (
      await runtime.request(
        `/api/v2/workflows/creation?projectId=${project.id}`,
      )
    ).json();
    const previousCalls = calls;
    for (const selected of [
      {
        id: first.id,
        version: first.version,
        representation: "summary",
        record: { id: summary.id, version: summary.version },
      },
      {
        id: first.id,
        version: first.version,
        representation: "paragraphs",
        paragraphIds: [paragraph.id],
      },
      {
        id: first.id,
        version: first.version,
        representation: "summary",
        record: { id: crypto.randomUUID(), version: 0 },
      },
      { id: huge.id, version: huge.version, representation: "original" },
    ]) {
      const blocked = await runtime.request("/api/v2/workflows/creation", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          projectId: project.id,
          operation: "chapter",
          targetId: target.id,
          baseVersion: target.version,
          instruction: "只用明确来源",
          engineKind: "codex",
          model: { modelId: "test-fixed-model" },
          narrativeContextRequest: {
            format: "narrative-context-v1",
            chapters: [selected],
          },
        }),
      });
      expect(blocked.status, await blocked.clone().text()).toBe(409);
    }
    expect(calls).toBe(previousCalls);
    expect(
      await (
        await runtime.request(
          `/api/v2/workflows/creation?projectId=${project.id}`,
        )
      ).json(),
    ).toEqual(before);
  }, 30000);

