  it("diagnosis retry after restart preserves the failed run's old intent, explicit scope and snapshot; a fresh run alone binds the new intent", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-diagnosis-retry-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let output: ReturnType<typeof diagnosisOutput>;
    let fail = true;
    const sent: string[] = [];
    const engine = host((prompt) => {
      sent.push(prompt);
      if (fail) throw new Error("受控诊断接口暂时不可用");
      return JSON.stringify(
        prompt.includes("审阅候选与冻结") ? { issues: [] } : output,
      );
    });
    const runtime = await fixture(undefined, engine, path);
    const { project, chapter } = await seed(runtime);
    output = diagnosisOutput(chapter.id, chapter.version);
    const old = await adoptIntent(
      runtime,
      project.id,
      intentContent("OLD DIAGNOSIS RETRY"),
    );
    const initial = await start(runtime, {
      projectId: project.id,
      operation: "adaptation-diagnosis",
      diagnosisRequest: await diagnosisRequest(runtime, project.id),
    });
    const failed = await until(runtime, initial.id, ["failed"]);
    await runtime.close();
    fail = false;
    const reopened = await fixture(undefined, engine, path);
    const newer = await adoptIntent(
      reopened,
      project.id,
      intentContent("NEW DIAGNOSIS RETRY"),
    );
    const retry = await reopened.request(
      `/api/v2/workflows/creation/${failed.id}/actions`,
      {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({ action: "retry" }),
      },
    );
    expect(retry.status, await retry.clone().text()).toBe(200);
    const retried = await retry.json();
    const ready = await until(reopened, retried.id, [
      "awaiting-review",
      "failed",
    ]);
    expect(ready.stage, ready.error).toBe("awaiting-review");
    expect(ready.sourceSnapshotId).toBe(failed.sourceSnapshotId);
    expect(ready.diagnosisBasis).toEqual(failed.diagnosisBasis);
    expect(ready.authorIntent).toMatchObject({
      id: old.id,
      version: old.version,
    });
    expect(
      sent.every(
        (prompt) =>
          prompt.includes("OLD DIAGNOSIS RETRY") &&
          !prompt.includes("NEW DIAGNOSIS RETRY"),
      ),
    ).toBe(true);
    const pending = await readDiagnosis(reopened, ready.diagnosisId!);
    expect(pending.sourceState).toBe("stale");
    expect((await transitionDiagnosis(reopened, pending, "adopt")).status).toBe(
      409,
    );
    const fresh = await until(
      reopened,
      (
        await start(reopened, {
          projectId: project.id,
          operation: "adaptation-diagnosis",
          diagnosisRequest: await diagnosisRequest(reopened, project.id),
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect(fresh.stage, fresh.error).toBe("awaiting-review");
    expect(fresh.authorIntent).toMatchObject({
      id: newer.id,
      version: newer.version,
    });
    expect(fresh.sourceSnapshotId).not.toBe(ready.sourceSnapshotId);
    expect(
      (
        await transitionDiagnosis(
          reopened,
          await readDiagnosis(reopened, fresh.diagnosisId!),
          "adopt",
        )
      ).status,
    ).toBe(200);
    expect(
      await (await reopened.request(`/api/v2/chapters/${chapter.id}`)).json(),
    ).toMatchObject({ content: "原正文保留。", version: chapter.version });
  }, 20000);

  it("diagnosis history, frozen provenance and durable adopted receipts recover after a real SQLite restart", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-diagnosis-"));
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite");
    let output: ReturnType<typeof diagnosisOutput>;
    const engine = host((prompt) =>
      JSON.stringify(
        prompt.includes("审阅候选与冻结") ? { issues: [] } : output,
      ),
    );
    const runtime = await fixture(undefined, engine, path);
    const { project, chapter } = await seed(runtime);
    output = diagnosisOutput(chapter.id, chapter.version);
    await adoptIntent(
      runtime,
      project.id,
      intentContent("PERSISTENT DIAGNOSIS"),
    );
    const ready = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "adaptation-diagnosis",
          diagnosisRequest: await diagnosisRequest(runtime, project.id),
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect(ready.stage, ready.error).toBe("awaiting-review");
    const pending = await readDiagnosis(runtime, ready.diagnosisId!);
    const key = crypto.randomUUID();
    expect(
      (await transitionDiagnosis(runtime, pending, "adopt", "reorder", key))
        .status,
    ).toBe(200);
    await runtime.close();
    const reopened = await fixture(undefined, engine, path);
    expect(await readDiagnosis(reopened, pending.id)).toMatchObject({
      sourceSnapshotId: ready.sourceSnapshotId,
      status: "adopted",
      selectedStrategyId: "reorder",
      isCurrent: true,
      sourceState: "current",
    });
    expect(
      (await transitionDiagnosis(reopened, pending, "adopt", "reorder", key))
        .status,
    ).toBe(200);
    expect((await until(reopened, ready.id, ["applied"])).stage).toBe(
      "applied",
    );
    expect(
      reopened
        .domainEvents()
        .filter((event) => event.type === "production.diagnosis-adopted.v1"),
    ).toHaveLength(1);
  }, 15000);

