  function controlledQuotedOutline(
    prompt: string,
    output: CreationContent,
    invalid = false,
  ) {
    if (!prompt.includes("逐场引文协议 exact-expression-quotes-v1"))
      return output;
    const sources = JSON.parse(
      prompt.match(/逐场可引用身份：(\[[^\n]*?\])。/u)![1]!,
    ) as NonNullable<
      EpisodeOutlineContent["scenes"][number]["sourceEvidence"]
    >[number]["source"][];
    const entries = [
      ...prompt.matchAll(
        /([^\s]+) \(source=(chapter|knowledge|project|production):([a-f0-9-]{36})@(\d+)\)\n([^\n]+)/gu,
      ),
    ].map((match) => ({
      path: match[1],
      kind: match[2],
      id: match[3],
      version: Number(match[4]),
      value: JSON.parse(match[5]!) as Record<string, unknown>,
    }));
    const parsed = EpisodeOutlineContentSchema.parse(output.items[0]!.data);
    return {
      ...output,
      items: output.items.map((item) => ({
        ...item,
        data: {
          ...parsed,
          scenes: parsed.scenes.map((scene, sceneIndex) => ({
            ...scene,
            sourceEvidence: sources.flatMap((source, sourceIndex) => {
              const entry = entries.find(
                (item) =>
                  item.path === source.fieldPath &&
                  item.kind === source.sourceKind &&
                  item.id === source.sourceId &&
                  item.version === source.sourceVersion,
              );
              if (!entry)
                throw new Error(
                  "Controlled quote requires actual frozen source text",
                );
              if (
                source.sourceKind === "chapter" &&
                !scene.sourceChapters.some(
                  (chapter) => chapter.id === source.sourceId,
                )
              )
                return [];
              let valuePath =
                source.sourceKind === "knowledge" ? "/summary" : "/content";
              let prose = entry.value[valuePath.slice(1)];
              if (source.sourceKind === "knowledge") {
                const coverage = entry.value.coveredChapters as
                  { id: string }[] | undefined;
                const chapter = entry.value.sourceChapter as
                  { id: string } | undefined;
                if (
                  !scene.sourceChapters.some(
                    (item) =>
                      chapter?.id === item.id ||
                      coverage?.some((c) => c.id === item.id),
                  )
                )
                  return [];
              }
              if (source.sourceKind === "project") {
                valuePath = "/content/synopsis";
                prose = (entry.value.content as { synopsis: string }).synopsis;
              }
              if (
                source.sourceKind === "production" &&
                Array.isArray(entry.value.blocks)
              ) {
                const index = entry.value.blocks.findIndex(
                  (block: { type: string; text?: string }) =>
                    ["action", "dialogue"].includes(block.type) &&
                    block.text?.trim(),
                );
                if (index !== -1) {
                  valuePath = `/blocks/${index}/text`;
                  prose = (entry.value.blocks[index] as { text: string }).text;
                }
              }
              if (typeof prose !== "string" || !prose.trim())
                throw new Error("Controlled quote requires actual prose");
              return [
                {
                  id: `quote-${sceneIndex}-${sourceIndex}`,
                  source,
                  valuePath,
                  quote: invalid
                    ? "NOT IN PROVIDED EXPRESSION"
                    : prose.slice(0, 20),
                  rationale: "PRIVATE MODEL DECLARED ATTRIBUTION",
                },
              ];
            }),
          })),
        },
      })),
    };
  }
  async function developmentFixture(
    path = ":memory:",
    approved = true,
    binaryHost?: DesktopHostClient,
    validateCommittedEvents = false,
    wholeBook = false,
    omitProductionPurgeRequestMigration = false,
    hierarchicalSummaryScope?: "volume" | "story-arc",
  ) {
    const sent: string[] = [];
    const fault = {
      remaining: 0,
      storyboardRemaining: 0,
      strategyRemaining: 0,
      strategyInvalidOnce: false,
      strategyInvalidAlways: false,
      quoteInvalid: false,
      ordinaryQualityClean: true,
      redoOutput: undefined as CreationContent | undefined,
      recordMergeCheckRemaining: 0,
    };
    const outputs = {
      narrativeSummary: undefined as CreationContent | undefined,
      chapterMemory: undefined as CreationContent | undefined,
      diagnosis: diagnosisOutput(crypto.randomUUID(), 0),
      quality: narrativeOutput(
        { kind: "episode-result", id: crypto.randomUUID(), version: 1 },
        false,
      ),
      plan: planOutput(crypto.randomUUID(), 0),
      strategy: strategyOutput(),
      outline: episodeOutlineOutput(crypto.randomUUID(), 0),
      script: episodeScriptOutput(),
      storyboard: storyboardOutput(episodeScriptOutput(), crypto.randomUUID()),
    };
    const engine = host((prompt) => {
      sent.push(prompt);
      if (
        outputs.chapterMemory &&
        prompt.includes("仅提取正文明确") &&
        !prompt.includes("审阅候选与冻结")
      ) {
        return JSON.stringify(outputs.chapterMemory);
      }
      if (
        prompt.includes("kind=narrative-summary") &&
        !prompt.includes("审阅候选与冻结")
      ) {
        if (!outputs.narrativeSummary)
          throw new Error("Actual summary response not prepared");
        return JSON.stringify(outputs.narrativeSummary);
      }
      if (
        fault.recordMergeCheckRemaining &&
        (prompt.includes("storyboard-record-field-merge-v1") ||
          prompt.includes("storyboard-record-field-merge-v2") ||
          prompt.includes("storyboard-record-field-merge-v3") ||
          prompt.includes("storyboard-record-field-merge-v4")) &&
        prompt.includes("审阅候选与冻结")
      ) {
        fault.recordMergeCheckRemaining--;
        throw new Error("controlled actual-field recheck failure");
      }
      if (
        prompt.includes("kind=adaptation-strategy") &&
        !prompt.includes("审阅候选与冻结") &&
        (fault.strategyInvalidAlways ||
          (fault.strategyInvalidOnce && !prompt.includes("仅修正列出的问题")))
      ) {
        const invalid = structuredClone(outputs.strategy);
        invalid.items[0]!.data.options[1] = {
          ...invalid.items[0]!.data.options[0]!,
          id: "relabeled-but-same-actions",
          title: "改个标题不算不同策略",
        };
        return JSON.stringify(invalid);
      }
      if (
        fault.strategyRemaining &&
        prompt.includes("kind=adaptation-strategy") &&
        !prompt.includes("审阅候选与冻结")
      ) {
        fault.strategyRemaining--;
        throw new Error("controlled independent strategy failure");
      }
      if (
        fault.storyboardRemaining &&
        prompt.includes("kind=storyboard-package") &&
        !prompt.includes("审阅候选与冻结")
      ) {
        fault.storyboardRemaining--;
        throw new Error("controlled storyboard failure");
      }
      if (
        fault.remaining &&
        prompt.includes("kind=episode-outline") &&
        !prompt.includes("审阅候选与冻结")
      ) {
        fault.remaining--;
        throw new Error("controlled episode failure");
      }
      return JSON.stringify(
        prompt.includes("审阅候选与冻结")
          ? { issues: [] }
          : prompt.includes("kind=narrative-quality-report")
            ? /目标：.*"kind":"(?:script|scene)"/u.test(prompt)
              ? ordinaryQualityOutput(prompt, fault.ordinaryQualityClean)
              : outputs.quality
            : prompt.includes("kind=episode-outline")
              ? controlledQuotedOutline(
                  prompt,
                  outputs.outline,
                  fault.quoteInvalid,
                )
              : prompt.includes("kind=storyboard-package")
                ? /协议 selected-(?:storyboard-(?:shots|block-structure)|scene-(?:shot|topology)-plan)-v1/u.test(
                    prompt,
                  ) && fault.redoOutput
                  ? fault.redoOutput
                  : outputs.storyboard
                : prompt.includes("kind=episode-script")
                  ? outputs.script
                  : prompt.includes("kind=adaptation-strategy")
                    ? outputs.strategy
                    : prompt.includes("kind=season-plan")
                      ? outputs.plan
                      : prompt.includes("故事圣经与视觉设定方案")
                        ? {
                            title: "正式故事圣经",
                            content: "正式人物设定",
                            items: [
                              {
                                ref: "bible",
                                kind: "story-bible",
                                title: "已批准林晚设定",
                                data: {
                                  内容: "APPROVED BIBLE: 林晚尚不知道姐姐去向，不虚构超能力。",
                                  依据: "作者明确审阅采用",
                                },
                              },
                            ],
                          }
                        : outputs.diagnosis,
      );
    });
    const runtime = await fixture(
      binaryHost,
      engine,
      path,
      validateCommittedEvents,
      false,
      false,
      omitProductionPurgeRequestMigration,
    );
    let { project, chapter } = await seed(runtime);
    let summaryTarget: { id: string; kind: "volume" | "story-arc" } | undefined;
    if (hierarchicalSummaryScope === "volume") {
      const created = await runtime.request(
        `/api/v2/projects/${project.id}/volumes`,
        {
          method: "POST",
          body: JSON.stringify({ projectId: project.id, title: "实际作者卷" }),
        },
      );
      expect(created.status, await created.clone().text()).toBe(201);
      const volume = (await created.json()) as { id: string };
      const moved = await runtime.request(`/api/v2/chapters/${chapter.id}`, {
        method: "PATCH",
        headers: { "If-Match": `"${chapter.version}"` },
        body: JSON.stringify({ version: chapter.version, volumeId: volume.id }),
      });
      expect(moved.status, await moved.clone().text()).toBe(200);
      chapter = await moved.json();
      summaryTarget = { id: volume.id, kind: "volume" };
    } else if (hierarchicalSummaryScope === "story-arc") {
      const created = await runtime.request("/api/v2/story-arcs", {
        method: "POST",
        body: JSON.stringify({
          projectId: project.id,
          title: "实际作者绑定弧",
          payload: {
            narrativeChapterScope: {
              format: "chapter-refs-v1",
              chapters: [{ id: chapter.id, version: chapter.version }],
            },
          },
        }),
      });
      expect(created.status, await created.clone().text()).toBe(201);
      const arc = (await created.json()) as { id: string };
      summaryTarget = { id: arc.id, kind: "story-arc" };
    }
    outputs.diagnosis = diagnosisOutput(chapter.id, chapter.version);
    outputs.plan = planOutput(chapter.id, chapter.version);
    outputs.outline = episodeOutlineOutput(chapter.id, chapter.version);
    const diagnosis = await adoptPlanDiagnosis(
      runtime,
      project.id,
      chapter.id,
      wholeBook,
    );
    const planRun = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "season-plan",
          seasonPlanRequest: await planRequest(runtime, project.id),
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect(planRun.stage, planRun.error).toBe("awaiting-review");
    const plan = await readPlan(runtime, planRun.seasonPlanId!);
    expect((await planAction(runtime, plan, "adopt")).status).toBe(200);
    const bible = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "knowledge-plan",
        })
      ).id,
      ["awaiting-review", "failed"],
    );
    expect(bible.stage, bible.error).toBe("awaiting-review");
    if (approved)
      expect((await commitCreation(runtime, bible.previewId!)).status).toBe(
        200,
      );
    return {
      runtime,
      project,
      chapter,
      plan,
      diagnosis,
      bible,
      summaryTarget,
      engine,
      outputs,
      sent,
      fault,
    };
  }
