  it("source confirmations native final event failures preserve materialized originals and recover once for Fountain, FDX and structured JSON", async () => {
    for (const format of ["fountain", "fdx", "script-json"] as const) {
      const directory = await mkdtemp(
        join(tmpdir(), `dramaip-native-confirmation-${format}-`),
      );
      temporaryDirectories.push(directory);
      const databasePath = join(directory, "native.sqlite");
      const data = await nativeIntakeFixture(
        format,
        databasePath,
        false,
        format === "script-json"
          ? JSON.stringify(structuredIntakeSource)
          : undefined,
      );
      let runtime = data.runtime;
      const send = () => runtime.request(`${data.getPath}/commit`, data.commit);
      runtime.failSourceConfirmationEvents("production", true);
      const failed = await send();
      expect(failed.status, await failed.clone().text()).toBe(500);
      expect(await failed.text()).not.toContain(
        "controlled source confirmation",
      );
      const pending = (await runtime
        .request(data.getPath)
        .then((r) =>
          r.json(),
        )) as import("@dramaip/contracts/production").ScreenplayIntakePreview;
      expect(pending.status).toBe("materialized");
      expect(pending.request).toEqual(data.input);
      expect(pending.receipt).toBeDefined();
      const originalStorage = runtime.ordinaryImportStorage();
      const projectId = pending.receipt!.projectId;
      const selected = await runtime
        .request(`/api/v2/projects/${projectId}`)
        .then((r) => r.json());
      expect(selected).toMatchObject({
        currentAdaptationId: pending.receipt!.adaptationId,
        version: 1,
      });
      expect(
        runtime
          .domainEvents()
          .filter(
            (event) => event.type === "production.creation-source-confirmed.v1",
          ),
      ).toHaveLength(0);
      await runtime.drainOutcomeEvents();
      const before = await runtime
        .request(`/api/v2/projects/${projectId}/creative-outcomes/summary`)
        .then((r) => r.json());
      expect(before.sourceConfirmations.recordedConfirmations).toBe(0);
      runtime.failSourceConfirmationEvents("production", false);
      await runtime.close();
      runtime = await fixture(undefined, undefined, databasePath, true);
      const accepted = await send();
      expect(accepted.status, await accepted.clone().text()).toBe(201);
      const saved =
        (await accepted.json()) as import("@dramaip/contracts/production").ScreenplayIntakePreview;
      expect(saved.status).toBe("committed");
      expect(saved.blocks).toEqual(data.preview.blocks);
      expect(saved.episodes).toEqual(data.preview.episodes);
      expect(saved.receipt).toEqual({
        ...pending.receipt,
        projectVersion: selected.version,
      });
      const after = runtime.ordinaryImportStorage();
      expect(after.production_records).toEqual(
        originalStorage.production_records,
      );
      expect(after.screenplay_documents).toEqual(
        originalStorage.screenplay_documents,
      );
      const events = runtime
        .domainEvents()
        .filter(
          (event) => event.type === "production.creation-source-confirmed.v1",
        );
      expect(events).toHaveLength(1);
      const event = events[0]!,
        fact = CreativeSourceConfirmationFactSchema.parse(event.payload);
      const receipt = saved.receipt!;
      const originals = receipt.episodes ?? [
        {
          previewEpisodeId: saved.id,
          scriptId: receipt.scriptId,
          scriptVersion: receipt.scriptVersion,
          documentId: receipt.documentId,
          documentVersion: receipt.documentVersion,
          scenes: [],
        },
      ];
      expect(event).toMatchObject({
        pluginId: "production",
        aggregateType: "screenplay-intake",
        aggregateId: saved.id,
        aggregateVersion: 3,
      });
      expect(fact).toMatchObject({
        sourceId: saved.id,
        projectId,
        projectVersion: selected.version,
        projectMode: "single_season",
        workflowPath: "adaptation",
        entry: "native-screenplay-intake",
        sourceFormat: format,
        contentKind: "script",
        entryCount: originals.length,
        sceneCount: originals.reduce(
          (sum, entry) => sum + entry.scenes.length,
          0,
        ),
        lossReportReviewed: true,
        entries: originals.map((entry, sourceIndex) => ({
          kind: "script-document",
          sourceIndex,
          previewEntryId: entry.previewEpisodeId,
          id: entry.documentId,
          version: entry.documentVersion,
          scriptId: entry.scriptId,
          scriptVersion: entry.scriptVersion,
        })),
      });
      for (const text of [
        data.preview.sourceName,
        String(data.commit.headers["Idempotency-Key"]),
        "林晚核对",
        "原房间资料",
        "保留作者意图",
      ])
        expect(JSON.stringify(fact)).not.toContain(text);
      expect(fact).not.toHaveProperty("sourceVersion");
      expect(fact.bindingFingerprint).toBe(
        createHash("sha256")
          .update(
            canonicalImportRequestJSON({
              request: data.input,
              preview: {
                id: data.preview.id,
                sourceFormat: data.preview.sourceFormat,
                etag: data.preview.etag,
                blocks: data.preview.blocks,
                episodes: data.preview.episodes,
                lossReport: data.preview.lossReport,
              },
            }),
          )
          .digest("hex"),
      );
      expect(fact.receiptFingerprint).toBe(
        createHash("sha256")
          .update(canonicalImportRequestJSON(receipt))
          .digest("hex"),
      );
      await runtime.drainOutcomeEvents();
      const summary = await runtime
        .request(`/api/v2/projects/${projectId}/creative-outcomes/summary`)
        .then((r) => r.json());
      expect(summary.sourceConfirmations).toMatchObject({
        recordedConfirmations: 1,
        items: [
          {
            ...fact,
            eventId: event.eventId,
            cursor: event.cursor,
            occurredAt: event.occurredAt,
          },
        ],
      });
      expect(
        summary.counts.every((row: { total: number }) => row.total === 0),
      ).toBe(true);
      expect(summary.goalConfirmations.recordedProjects).toBe(0);
      expect((await send()).status).toBe(201);
      expect(runtime.ordinaryImportStorage()).toEqual(after);
      runtime.rewindOutcomeCheckpoint();
      await runtime.close();
      runtime = await fixture(undefined, undefined, databasePath, true);
      await runtime.drainOutcomeEvents();
      expect((await send()).status).toBe(201);
      expect(
        runtime.domainEvents().filter((item) => item.type === event.type),
      ).toEqual(events);
      expect(
        (
          await runtime
            .request(`/api/v2/projects/${projectId}/creative-outcomes/summary`)
            .then((r) => r.json())
        ).sourceConfirmations,
      ).toEqual(summary.sourceConfirmations);
    }
  });

  it("source confirmations do not backfill committed legacy ordinary or native receipts from GET, same-key retry or historical generic events", async () => {
    const data = await nativeIntakeFixture("fountain");
    const runtime = data.runtime;
    const saved = await runtime
      .request(`${data.getPath}/commit`, data.commit)
      .then((r) => r.json());
    expect(saved.status).toBe("committed");
    await runtime.drainOutcomeEvents();
    runtime.forgetLegacySourceConfirmation(saved.id);
    const before = runtime.ordinaryImportStorage();
    runtime.rewindOutcomeCheckpoint();
    await runtime.drainOutcomeEvents();
    expect((await runtime.request(data.getPath)).status).toBe(200);
    expect(
      (await runtime.request(`${data.getPath}/commit`, data.commit)).status,
    ).toBe(201);
    expect(runtime.ordinaryImportStorage()).toEqual(before);
    expect(
      (
        await runtime
          .request(
            `/api/v2/projects/${saved.receipt.projectId}/creative-outcomes/summary`,
          )
          .then((r) => r.json())
      ).sourceConfirmations.recordedConfirmations,
    ).toBe(0);

    const ordinary = await fixture({
      readGrantedDocument: async () => ({
        name: "原资料.md",
        format: "markdown",
        size: 20,
        content: "# 原资料\n\n## 第一章\n\n林晚收信。",
      }),
    } as unknown as DesktopHostClient);
    const created = await ordinary
      .request("/api/v2/projects", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          title: "其他项目来源",
          mode: "personal_theater",
        }),
      })
      .then((r) => r.json());
    const source = await ordinary
      .request("/api/v2/source-imports/preview", {
        method: "POST",
        body: JSON.stringify({
          projectId: created.project.id,
          capabilityToken: crypto.randomUUID(),
        }),
      })
      .then((r) => r.json());
    const requestKey = crypto.randomUUID();
    const input = {
      projectId: created.project.id,
      strategy: "append",
      rightsConfirmed: true,
      destructiveConfirmed: false,
      preview: source.preview,
    };
    const send = () =>
      ordinary.request(`/api/v2/source-imports/${source.importId}/commit`, {
        method: "POST",
        headers: { "Idempotency-Key": requestKey },
        body: JSON.stringify(input),
      });
    expect((await send()).status).toBe(201);
    await ordinary.drainOutcomeEvents();
    const summary = await ordinary
      .request(
        `/api/v2/projects/${created.project.id}/creative-outcomes/summary`,
      )
      .then((r) => r.json());
    expect(summary.sourceConfirmations.byWorkflow).toEqual([
      { workflowPath: "novel", total: 0 },
      { workflowPath: "adaptation", total: 0 },
      { workflowPath: null, total: 1 },
    ]);
    expect(summary.sourceConfirmations.items[0].workflowPath).toBeNull();
    ordinary.forgetLegacySourceConfirmation(source.importId);
    ordinary.rewindOutcomeCheckpoint();
    await ordinary.drainOutcomeEvents();
    const old = ordinary.ordinaryImportStorage();
    const recovered = await ordinary.request(
      `/api/v2/source-imports/${source.importId}/commit?${new URLSearchParams({ projectId: created.project.id, requestKey })}`,
    );
    expect(recovered.status).toBe(200);
    expect(await recovered.json()).toMatchObject({ state: "committed", input });
    ordinary.failSourceConfirmationEvents("workspace", true);
    expect((await send()).status).toBe(201);
    expect(ordinary.ordinaryImportStorage()).toEqual(old);
    expect(
      (
        await ordinary
          .request(
            `/api/v2/projects/${created.project.id}/creative-outcomes/summary`,
          )
          .then((r) => r.json())
      ).sourceConfirmations.recordedConfirmations,
    ).toBe(0);
  });

  it("source confirmations replay while the original project is trashed and retain original versions on restore, but never resurrect purged scope", async () => {
    const directory = await mkdtemp(join(tmpdir(), "dramaip-source-scope-"));
    temporaryDirectories.push(directory);
    const databasePath = join(directory, "scope.sqlite");
    const data = await nativeIntakeFixture("fountain", databasePath);
    let runtime = data.runtime;
    const saved = await runtime
      .request(`${data.getPath}/commit`, data.commit)
      .then((r) => r.json());
    expect(saved.status).toBe("committed");
    const projectId = saved.receipt.projectId;
    await runtime.drainOutcomeEvents();
    const original = await runtime
      .request(`/api/v2/projects/${projectId}/creative-outcomes/summary`)
      .then((r) => r.json());
    expect(original.sourceConfirmations.recordedConfirmations).toBe(1);
    expect(
      (
        await runtime.request(`/api/v2/projects/${projectId}/trash`, {
          method: "POST",
        })
      ).status,
    ).toBe(200);
    // Simulate projection not yet recorded, preserving the real owner event.
    runtime.forgetSourceConfirmationProjection(saved.id);
    runtime.rewindOutcomeCheckpoint();
    await runtime.close();
    runtime = await fixture(undefined, undefined, databasePath, true);
    await runtime.drainOutcomeEvents();
    expect(runtime.sourceConfirmationStorage()).toHaveLength(1);
    const { bindingDisplay, ...originalRecord } =
      original.sourceConfirmations.items[0];
    expect(bindingDisplay).toBe("first-five-original-bindings");
    expect(
      JSON.parse(String(runtime.sourceConfirmationStorage()[0]!.record_json)),
    ).toEqual(originalRecord);
    expect(
      (
        await runtime.request(
          `/api/v2/projects/${projectId}/creative-outcomes/summary`,
        )
      ).status,
    ).toBe(404);
    const restored = await runtime
      .request(`/api/v2/projects/${projectId}/restore`, { method: "POST" })
      .then((r) => r.json());
    expect(restored.version).toBe(saved.receipt.projectVersion + 2);
    expect(
      (
        await runtime
          .request(`/api/v2/projects/${projectId}/creative-outcomes/summary`)
          .then((r) => r.json())
      ).sourceConfirmations,
    ).toEqual(original.sourceConfirmations);
    expect(
      (
        await runtime.request(`/api/v2/projects/${projectId}/trash`, {
          method: "POST",
        })
      ).status,
    ).toBe(200);
    expect(
      (
        await runtime.request(`/api/v2/projects/${projectId}`, {
          method: "DELETE",
          body: JSON.stringify({ confirmationTitle: restored.title }),
        })
      ).status,
    ).toBe(204);
    expect(runtime.sourceConfirmationStorage()).toEqual([]);
    runtime.rewindOutcomeCheckpoint();
    await runtime.close();
    runtime = await fixture(undefined, undefined, databasePath, true);
    await runtime.drainOutcomeEvents();
    expect(runtime.sourceConfirmationStorage()).toEqual([]);
    expect(
      (
        await runtime.request(`/api/v2/projects/${projectId}/restore`, {
          method: "POST",
        })
      ).status,
    ).toBe(404);
    expect(
      await runtime.request("/api/v2/projects").then((r) => r.json()),
    ).toEqual([]);
  });

