  it("projectless JSON all-episode materialization rolls back actual partial inserts and resumes same receipt after every persistent write boundary", async () => {
    for (const stage of ["project", "materialize", "finalize"] as const) {
      const directory = await mkdtemp(
        join(tmpdir(), "dramaip-json-intake-recovery-"),
      );
      temporaryDirectories.push(directory);
      const path = join(directory, "runtime.sqlite");
      const data = await nativeIntakeFixture(
        "script-json",
        path,
        false,
        JSON.stringify(structuredIntakeSource),
      );
      const allocations = data.runtime.allocationCounts();
      data.runtime.failNativeIntakeWrite(
        stage,
        stage === "materialize" ? 2 : undefined,
      );
      const rejected = await data.runtime.request(
        `${data.getPath}/commit`,
        data.commit,
      );
      expect(rejected.status).toBe(500);
      expect(rejected.headers.get("Content-Type")).toBe(
        "application/problem+json",
      );
      const interrupted = await (
        await data.runtime.request(data.getPath)
      ).json();
      expect(interrupted.status).toBe(
        stage === "finalize" ? "materialized" : "creating",
      );
      expect(interrupted.episodes).toEqual(data.preview.episodes);
      const projects = await (
        await data.runtime.request("/api/v2/projects")
      ).json();
      expect(projects).toHaveLength(stage === "project" ? 0 : 1);
      if (projects.length)
        for (const [kind, count] of [
          ["adaptations", 1],
          ["episodes", 2],
          ["scripts", 2],
          ["scenes", 3],
        ] as const)
          expect(
            await (
              await data.runtime.request(
                `/api/v2/${kind}?projectId=${projects[0].id}`,
              )
            ).json(),
          ).toHaveLength(stage === "finalize" ? count : 0);
      expect(data.runtime.allocationCounts()).toEqual(allocations);
      await data.runtime.close();
      const restored = await fixture(undefined, undefined, path);
      const before = restored.domainEvents();
      expect(await (await restored.request(data.getPath)).json()).toEqual(
        interrupted,
      );
      expect(restored.domainEvents()).toEqual(before);
      expect(
        (
          await restored.request(`${data.getPath}/commit`, {
            ...data.commit,
            body: JSON.stringify({
              ...data.input,
              project: { ...data.input.project, title: "不能替换冻结输入" },
            }),
          })
        ).status,
      ).toBe(409);
      const resumed = await restored.request(
        `${data.getPath}/commit`,
        data.commit,
      );
      expect(resumed.status, await resumed.clone().text()).toBe(201);
      const saved = await resumed.json();
      expect(saved).toMatchObject({
        status: "committed",
        sourceState: "current",
        episodes: data.preview.episodes,
        request: data.input,
        receipt: { projectVersion: 1 },
      });
      expect(saved.receipt.episodes).toHaveLength(2);
      if (interrupted.receipt)
        expect(saved.receipt.episodes).toEqual(interrupted.receipt.episodes);
      expect(
        await (await restored.request("/api/v2/projects")).json(),
      ).toHaveLength(1);
      for (const [kind, count] of [
        ["adaptations", 1],
        ["episodes", 2],
        ["scripts", 2],
        ["scenes", 3],
      ] as const)
        expect(
          await (
            await restored.request(
              `/api/v2/${kind}?projectId=${saved.receipt.projectId}`,
            )
          ).json(),
        ).toHaveLength(count);
      const events = restored.domainEvents();
      expect(
        await (
          await restored.request(`${data.getPath}/commit`, data.commit)
        ).json(),
      ).toEqual(saved);
      expect(restored.domainEvents()).toEqual(events);
      expect(data.reads()).toBe(1);
      await restored.close();
    }
  }, 35000);

