  it.each(["fountain", "fdx"] as const)(
    "projectless native %s initialization survives each actual write-boundary rollback and SQLite restart without duplicates",
    async (format) => {
      for (const stage of ["project", "materialize", "finalize"] as const) {
        const directory = await mkdtemp(
          join(tmpdir(), "dramaip-native-intake-recovery-"),
        );
        temporaryDirectories.push(directory);
        const data = await nativeIntakeFixture(
          format,
          join(directory, "runtime.sqlite"),
        );
        data.runtime.failNativeIntakeWrite(stage);
        const failure = await data.runtime.request(
          `${data.getPath}/commit`,
          data.commit,
        );
        expect(failure.status).toBe(500);
        expect(failure.headers.get("Content-Type")).toBe(
          "application/problem+json",
        );
        expect(await failure.json()).toMatchObject({
          status: 500,
          code: "SCREENPLAY_INTAKE",
        });
        const interrupted = await (
          await data.runtime.request(data.getPath)
        ).json();
        expect(interrupted.status).toBe(
          stage === "finalize" ? "materialized" : "creating",
        );
        const projects = await (
          await data.runtime.request("/api/v2/projects")
        ).json();
        expect(projects.length).toBe(stage === "project" ? 0 : 1);
        if (projects.length)
          expect(
            (
              await (
                await data.runtime.request(
                  `/api/v2/scripts?projectId=${projects[0].id}`,
                )
              ).json()
            ).length,
          ).toBe(stage === "finalize" ? 1 : 0);
        const beforeRead = data.runtime.domainEvents();
        expect(await (await data.runtime.request(data.getPath)).json()).toEqual(
          interrupted,
        );
        expect(data.runtime.domainEvents()).toEqual(beforeRead);
        await data.runtime.close();
        const restored = await fixture(undefined, undefined, data.path);
        expect(await (await restored.request(data.getPath)).json()).toEqual(
          interrupted,
        );
        const resumed = await restored.request(
          `${data.getPath}/commit`,
          data.commit,
        );
        expect(resumed.status, await resumed.clone().text()).toBe(201);
        const saved = await resumed.json();
        expect(saved).toMatchObject({
          status: "committed",
          sourceState: "current",
          blocks: data.preview.blocks,
          receipt: { projectVersion: 1, documentVersion: 0, scriptVersion: 0 },
        });
        expect(
          (await (await restored.request("/api/v2/projects")).json()).length,
        ).toBe(1);
        expect(
          (
            await (
              await restored.request(
                `/api/v2/scripts?projectId=${saved.receipt.projectId}`,
              )
            ).json()
          ).length,
        ).toBe(1);
        const exact = await (await restored.request(data.getPath)).json();
        expect(
          await (
            await restored.request(`${data.getPath}/commit`, data.commit)
          ).json(),
        ).toEqual(exact);
        expect(data.reads()).toBe(1);
        await restored.close();
      }
    },
    35000,
  );

