  it("direct development rejects wrong source identity, privacy and full first-prompt budget before context/task/model allocation, forbids downstream root rebinding and fake scene chapters", async () => {
    const data = await directDevelopmentFixture("script");
    const { runtime, project, direct } = data;
    const request = await data.request("episode-outline");
    const baseline = async () => ({
      contexts: runtime.allocationCounts(),
      tasks: await (await runtime.request("/api/v2/tasks")).json(),
      events: runtime.domainEvents(),
      calls: data.sent.length,
    });
    const reject = async (
      value: unknown,
      instruction = "仅用真实原稿",
      expected = 409,
    ) => {
      const before = await baseline();
      const response = await runtime.request("/api/v2/workflows/creation", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          projectId: project.id,
          operation: "episode-outline",
          engineKind: "codex",
          instruction,
          episodeDevelopmentRequest: value,
        }),
      });
      expect(response.status, await response.clone().text()).toBe(expected);
      expect(await baseline()).toEqual(before);
    };
    await reject(
      { ...request, seasonPlan: { id: crypto.randomUUID(), version: 0 } },
      "不混用",
      400,
    );
    await reject({
      ...request,
      direct: {
        ...direct,
        project: { ...direct.project, id: crypto.randomUUID() },
      },
    });
    await reject({
      ...request,
      direct: {
        ...direct,
        sourceScript: {
          ...direct.sourceScript,
          version: direct.sourceScript!.version + 1,
        },
      },
    });
    await reject({
      ...request,
      direct: {
        ...direct,
        sourceScript: { ...direct.sourceScript, id: crypto.randomUUID() },
      },
    });
    let policyVersion = 0;
    const policy = async (fieldPath?: string) => {
      const response = await runtime.request(
        `/api/v2/projects/${project.id}/agent-context-policies`,
        {
          method: "PUT",
          headers: { "If-Match": `"${policyVersion}"` },
          body: JSON.stringify({
            version: policyVersion,
            policies: fieldPath ? [{ fieldPath, mode: "never" }] : [],
          }),
        },
      );
      expect(response.status).toBe(200);
      policyVersion++;
    };
    for (const fieldPath of [
      "/project",
      `/production/${direct.sourceScript!.id}`,
      AUTHOR_INTENT_CONTEXT_PATH,
    ]) {
      await policy(fieldPath);
      await reject(request);
    }
    await policy();
    await reject(request, "要求".repeat(45000));
    const outlineRun = await generateDevelopment(
      runtime,
      project.id,
      "episode-outline",
      request,
    );
    expect((await commitCreation(runtime, outlineRun.previewId!)).status).toBe(
      200,
    );
    const nextRequest = await data.request("episode-script");
    const before = await baseline();
    const changed = await runtime.request("/api/v2/workflows/creation", {
      method: "POST",
      headers: { "Idempotency-Key": crypto.randomUUID() },
      body: JSON.stringify({
        projectId: project.id,
        operation: "episode-script",
        engineKind: "codex",
        instruction: "不要静默改变来源时长",
        episodeDevelopmentRequest: {
          ...nextRequest,
          direct: { ...direct, durationSeconds: 120 },
        },
      }),
    });
    expect(changed.status, await changed.clone().text()).toBe(409);
    expect(await baseline()).toEqual(before);
    const valid = structuredClone(data.outputs.outline);
    (
      data.outputs.outline.items[0]!.data.scenes as {
        sourceChapters: { id: string; version: number }[];
      }[]
    )[0]!.sourceChapters = [{ id: crypto.randomUUID(), version: 0 }];
    const invalid = await until(
      runtime,
      (
        await start(runtime, {
          projectId: project.id,
          operation: "episode-outline",
          episodeDevelopmentRequest: await data.request("episode-outline"),
        })
      ).id,
      ["failed"],
    );
    expect(invalid.episodeResultId).toBeUndefined();
    expect(invalid.issues.length).toBeGreaterThan(0);
    data.outputs.outline = valid;
  }, 35000);

