  it("production quality sources inherit real formal screenplay and scene receipts and every frozen privacy dependency without upgrading copied markers", async () => {
    const folder = await mkdtemp(join(tmpdir(), "production-quality-formal-"));
    temporaryDirectories.push(folder);
    const path = join(folder, "runtime.sqlite");
    const data = await developmentFixture(path);
    const storyboard = await adoptedPilot(data);
    const scenes = storyboard.productionRecords!.filter(
      (item) => item.kind === "scenes",
    );
    expect(scenes.length).toBeGreaterThan(0);
    const originalSources: ProductionQualitySource[] = [];
    for (const scene of scenes) {
      const source = await productionQualityGet(
        data.runtime,
        data.project.id,
        scene.id,
      );
      expect(source.source.state, JSON.stringify(source)).toBe("available");
      if (source.source.state !== "available")
        throw new Error("Actual scene missing");
      originalSources.push(source);
      expect(source.source.record.id).toBe(scene.id);
      expect(source.source.policyDependencies).toEqual(
        expect.arrayContaining(
          storyboard.basis.references.map(
            ({ sourceId, sourceVersion, fieldPath }) => ({
              sourceId,
              sourceVersion,
              fieldPath,
            }),
          ),
        ),
      );
      const allocations = data.runtime.allocationCounts(),
        events = data.runtime.domainEvents();
      for (const dependency of source.source.policyDependencies) {
        const preview = data.runtime.previewProductionQualitySource(
          data.project.id,
          scene.id,
          [
            { fieldPath: `/production/${scene.id}`, mode: "always" },
            { fieldPath: dependency.fieldPath, mode: "never" },
          ],
        );
        expect(preview.entries[0], dependency.fieldPath).toMatchObject({
          included: false,
          mode: "never",
        });
      }
      expect(data.runtime.allocationCounts()).toEqual(allocations);
      expect(data.runtime.domainEvents()).toEqual(events);
    }
    const actualScene = (
      originalSources[0]!.source as Extract<
        ProductionQualitySource["source"],
        { state: "available" }
      >
    ).record;
    const copied = await productionQualityCreate(data.runtime, "scenes", {
      projectId: data.project.id,
      parentId: actualScene.parentId,
      title: "只有复制标签，不是真实采用",
      payload: {
        场景动作: "另一个独立人工动作。",
        sourceWorkflowId: storyboard.workflowId,
        storyboardResultId: storyboard.id,
      },
    });
    expect(
      (await productionQualityGet(data.runtime, data.project.id, copied.id))
        .source,
    ).toEqual({ state: "unavailable", reason: "lineage-unavailable" });
    const calls = data.sent.length,
      storage = data.runtime.screenplaySourceStorage();
    await data.runtime.close();
    const restored = await fixture(undefined, data.engine, path);
    for (const source of originalSources)
      expect(
        await productionQualityGet(restored, data.project.id, source.id),
      ).toEqual(source);
    expect(restored.screenplaySourceStorage()).toEqual(storage);
    expect(data.sent).toHaveLength(calls);
    restored.forgetProductionQualityReceipt(storyboard.workflowId!);
    const after = restored.screenplaySourceStorage(),
      events = restored.domainEvents();
    expect(
      (await productionQualityGet(restored, data.project.id, actualScene.id))
        .source,
    ).toEqual({ state: "unavailable", reason: "lineage-unavailable" });
    expect(restored.screenplaySourceStorage()).toEqual(after);
    expect(restored.domainEvents()).toEqual(events);
  }, 60000);

