  it("author-frozen scene shot plan blocks complete actual/source privacy and prompt budget before allocation and refuses model metadata escapes", async () => {
    const data = await authorShotPlanFixture();
    let version = 0;
    const policy = async (fieldPath?: string) => {
      expect(
        (
          await data.runtime.request(
            `/api/v2/projects/${data.project.id}/agent-context-policies`,
            {
              method: "PUT",
              headers: { "If-Match": `"${version}"` },
              body: JSON.stringify({
                version,
                policies: fieldPath ? [{ fieldPath, mode: "never" }] : [],
              }),
            },
          )
        ).status,
      ).toBe(200);
      version++;
    };
    const attempt = (instruction = "只生成作者明确镜头计划") =>
      data.runtime.request("/api/v2/workflows/creation", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          projectId: data.project.id,
          operation: "storyboard-package",
          instruction,
          engineKind: "codex",
          model: { modelId: "test-fixed-model" },
          episodeDevelopmentRequest: data.request,
        }),
      });
    for (const path of [
      `/production/${data.base.id}`,
      `/production/${data.old.id}`,
      `/production/${data.sceneRecord.id}`,
      `/production/${data.base.scriptId}`,
      `/production/${data.base.basis.request.script!.id}`,
      `/chapters/${data.base.basis.chapters[0]!.id}`,
    ]) {
      await policy(path);
      const counts = data.runtime.allocationCounts(),
        calls = data.sent.length;
      expect((await attempt()).status).toBe(409);
      expect(data.runtime.allocationCounts()).toEqual(counts);
      expect(data.sent.length).toBe(calls);
    }
    await policy();
    const counts = data.runtime.allocationCounts(),
      calls = data.sent.length;
    expect((await attempt("要求".repeat(45000))).status).toBe(409);
    expect(data.runtime.allocationCounts()).toEqual(counts);
    expect(data.sent.length).toBe(calls);
    const before = data.runtime.scriptMergeStorage().productionRecords;
    const raw = StoryboardSceneShotPlanPatchSchema.parse(
      data.fault.redoOutput!.items[0]!.data,
    );
    for (const patch of [
      { ...raw, format: "selected-storyboard-shots-v1" },
      { ...raw, shots: [{ ...raw.shots[0], durationSeconds: 44 }] },
      { ...raw, shots: [{ ...raw.shots[0], id: "shot-0" }] },
    ]) {
      data.fault.redoOutput!.items[0]!.data = patch;
      const started = await attempt();
      expect(started.status).toBe(200);
      const failed = await until(data.runtime, (await started.json()).id, [
        "failed",
      ]);
      expect(failed.previewId).toBeUndefined();
      expect(data.runtime.scriptMergeStorage().productionRecords).toEqual(
        before,
      );
    }
  }, 45000);

