  async function topologyRedoFixture(
    path = ":memory:",
    variant: "reorder" | "replace" = "reorder",
  ) {
    const data = await topologyRevisionFixture(path),
      { runtime, project } = data.data;
    if (variant === "replace") {
      if (
        data.script.content.kind !== "episode-script" ||
        data.outline.content.kind !== "episode-outline"
      )
        throw new Error("original actual pair required");
      const outline = structuredClone(data.outline.content.value),
        links = structuredClone(data.script.content.value.sceneLinks);
      outline.scenes[1]!.id = crypto.randomUUID();
      outline.scenes[1]!.beats.forEach((beat) => {
        beat.id = crypto.randomUUID();
      });
      links[1]!.sceneId = outline.scenes[1]!.id;
      const originalBlocks = data.script.content.value.blocks,
        blocks = links.flatMap((link, index) =>
          link.blockIds.map((id) => {
            const block = structuredClone(
              originalBlocks.find((block) => block.id === id)!,
            );
            if (index === 1) block.id = crypto.randomUUID();
            return block;
          }),
        );
      links[1]!.blockIds = blocks
        .filter((block) => !links[0]!.blockIds.includes(block.id))
        .map((block) => block.id);
      const saved = await runtime.request(
        `/api/v2/scripts/${data.script.scriptId}/screenplay`,
        {
          method: "PATCH",
          headers: { "If-Match": `"${data.actual.version}"` },
          body: JSON.stringify({ version: data.actual.version, blocks }),
        },
      );
      expect(saved.status, await saved.clone().text()).toBe(200);
      data.input.documentVersion = (await saved.json()).version;
      data.input.outlineContent = outline;
      data.input.sceneLinks = links;
    }
    const previewResponse = await data.preview();
    expect(previewResponse.status).toBe(200);
    const preview = (await previewResponse.json()) as EpisodeTopologyRevision;
    const adoptResponse = await runtime.request(
      `/api/v2/episode-topology-revisions/${preview.id}/adopt`,
      {
        method: "POST",
        headers: { "If-Match": '"0"', "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({
          stateVersion: 0,
          confirmation: data.confirmation,
        }),
      },
    );
    expect(adoptResponse.status, await adoptResponse.clone().text()).toBe(200);
    const pair = (await adoptResponse.json()) as EpisodeTopologyRevision;
    if (data.board.content.kind !== "storyboard-package")
      throw new Error("actual original board required");
    const base = data.board.content.value,
      bindings = data.board.productionRecords!;
    const binding = (stableId: string, kind: "scenes" | "shots") =>
      bindings.find(
        (item) => item.stableId === stableId && item.kind === kind,
      )!;
    const desired = preview.outlineContent.scenes.map((scene, index) => {
      const previous = base.scenes.find((item) => item.sceneId === scene.id),
        record = previous && binding(scene.id, "scenes");
      return {
        sceneId: scene.id,
        orderIndex: scene.orderIndex,
        durationSeconds: scene.durationSeconds,
        mode:
          variant === "replace" && index === 0
            ? ("retain" as const)
            : ("generate" as const),
        ...(record
          ? { retains: { recordId: record.id, version: record.version } }
          : {}),
        shots: (previous ?? base.scenes[index]!).shots.map((shot) => {
          const row = previous && binding(shot.id, "shots");
          return {
            id: previous ? shot.id : crypto.randomUUID(),
            orderIndex: shot.orderIndex,
            durationSeconds: shot.durationSeconds,
            assetIds: shot.assetIds,
            ...(row
              ? { retains: { recordId: row.id, version: row.version } }
              : {}),
          };
        }),
      };
    });
    const patch = {
      format: "selected-scene-topology-plan-v1",
      shots: desired.flatMap((scene, index) =>
        scene.mode === "generate"
          ? scene.shots.map((shot) => ({
              ...base.scenes[index]!.shots[0]!,
              id: shot.id,
              orderIndex: shot.orderIndex,
              durationSeconds: shot.durationSeconds,
              assetIds: shot.assetIds,
              sourceBlockIds: preview.scriptContent.sceneLinks.find(
                (link) => link.sceneId === scene.sceneId,
              )!.blockIds,
              visualAction: `明确新拓扑表达 ${shot.id}`,
            }))
          : [],
      ),
      subtitles: [],
      costRisks: [],
    };
    data.data.fault.redoOutput = {
      title: "受控场景拓扑局部候选",
      content: "只写明确新范围，不证明质量",
      items: [
        {
          ref: "topology",
          kind: "storyboard-package",
          title: "受控局部",
          data: patch,
        },
      ],
    };
    const request = {
      ...(await developmentRequest(runtime, project.id, "storyboard-package")),
      redoMode: "scene-topology-plan" as const,
      redoTopologyPlan: {
        format: "author-scene-topology-plan-v1" as const,
        scenes: desired,
        retiredScenes: base.scenes
          .filter(
            (scene) => !desired.some((next) => next.sceneId === scene.sceneId),
          )
          .map((scene) => ({
            sceneId: scene.sceneId,
            recordId: binding(scene.sceneId, "scenes").id,
            version: binding(scene.sceneId, "scenes").version,
          })),
        retiredShots: base.scenes.flatMap((scene) =>
          scene.shots
            .filter(
              (shot) =>
                !desired.some((next) =>
                  next.shots.some((item) => item.id === shot.id),
                ),
            )
            .map((shot) => ({
              shotId: shot.id,
              recordId: binding(shot.id, "shots").id,
              version: binding(shot.id, "shots").version,
            })),
        ),
      },
      redoShots: base.scenes
        .filter(
          (scene) =>
            !desired.some(
              (next) =>
                next.sceneId === scene.sceneId && next.mode === "retain",
            ),
        )
        .flatMap((scene) =>
          scene.shots.map((shot) => {
            const row = binding(shot.id, "shots");
            return { shotId: shot.id, recordId: row.id, version: row.version };
          }),
        ),
    };
    const response = await runtime.request("/api/v2/workflows/creation", {
      method: "POST",
      headers: { "Idempotency-Key": crypto.randomUUID() },
      body: JSON.stringify({
        projectId: project.id,
        operation: "storyboard-package",
        instruction: "作者明确冻结新场景拓扑和原实际身份，仅生成选中表达。",
        sourceIds: [],
        engineKind: "codex",
        model: { modelId: "test-fixed-model" },
        episodeDevelopmentRequest: request,
      }),
    });
    expect(response.status, await response.clone().text()).toBe(200);
    const run = await until(runtime, (await response.json()).id, [
      "awaiting-review",
      "failed",
    ]);
    expect(run.stage, run.error).toBe("awaiting-review");
    expect(run.episodeDevelopmentBasis?.storyboardRedo).toMatchObject({
      scope: "author-frozen-scene-topology-plan-v1",
      base: { id: data.board.id, version: data.board.version },
      previousScript: { id: data.script.id, version: data.script.version },
      semanticVerification: "unverified",
    });
    return { data, run, pair, desired, request };
  }
