    expect(runtime.scriptMergeStorage().productionRecords).toEqual(before);
    expect((await (await submit()).json()).id).toBe(merged.id);
    const committed = await commitCreation(runtime, merged.previewId!);
    expect(committed.status, await committed.clone().text()).toBe(200);
    const kept = (await (
      await runtime.request(`/api/v2/shots/${old.id}`)
    ).json()) as ProductionRecord;
