      (await comparison.json()) as import("@dramaip/contracts/production").ProductionRecordMergeComparison;
    expect(report.format).toBe("storyboard-record-field-comparison-v4");
    expect(report.units).toEqual([]);
    expect(report.records.every((row) => !row.editable)).toBe(true);
