    const secondResponse = await planAction(runtime, accepted, "reorder", {
      confirmed: true,
      episodeIds: ["stable-episode-0", "stable-episode-1"],
    });
    expect(secondResponse.status, await secondResponse.clone().text()).toBe(
      200,
    );
    const second = (await secondResponse.json()) as SeasonPlan;
    expect(second.basis.baseAdoptedId).toBe(accepted.id);
    expect((await planAction(runtime, second, "adopt")).status).toBe(200);
    expect((await readPlan(runtime, second.id)).isCurrent).toBe(true);
    expect(
      await (
        await planAction(
          runtime,
          edited,
          "adopt",
          { confirmed: true },
          adoptKey,
        )
      ).json(),
    ).toMatchObject({ id: edited.id, isCurrent: false });
    expect((await readPlan(runtime, second.id)).isCurrent).toBe(true);
    expect((await planAction(runtime, original, "adopt")).status).toBe(409);
    await runtime.close();
    const reopened = await fixture(undefined, engine, path);
    expect(await readPlan(reopened, second.id)).toMatchObject({
      status: "adopted",
      isCurrent: true,
      sourcePlanId: accepted.id,
    });
    expect((await until(reopened, ready.id, ["applied"])).seasonPlanId).toBe(
      second.id,
    );
    expect(
      await (
        await planAction(reopened, original, "reorder", order, reorderKey)
      ).json(),
    ).toMatchObject({ id: edited.id, isCurrent: false });
    const firstPage = (await (
      await reopened.request(
        `/api/v2/projects/${project.id}/season-plans?limit=1`,
      )
    ).json()) as { items: SeasonPlan[]; nextCursor: string };
