  for (const operation of ["adaptation-strategy", "season-plan"] as const) {
    it(`creation adoption quality rejects a historical pending ${operation} through its own route and retains exact candidate and adopted head`, async () => {
      const directory = await mkdtemp(
        join(tmpdir(), "dramaip-m4-historical-production-gate-"),
      );
      temporaryDirectories.push(directory);
      const path = join(directory, "runtime.sqlite");
      const data = await developmentFixture(path);
      const { runtime, project, chapter } = data;
      const oldPlan = await readPlan(runtime, data.plan.id);
      const workflow =
        operation === "adaptation-strategy"
          ? await strategyRun(runtime, project.id)
          : await until(
              runtime,
              (
                await start(runtime, {
                  projectId: project.id,
                  operation,
                  seasonPlanRequest: await planRequest(runtime, project.id),
                })
              ).id,
              ["awaiting-review", "failed"],
            );
      expect(workflow.stage, workflow.error).toBe("awaiting-review");
      const candidate =
        operation === "adaptation-strategy"
          ? await readStrategy(runtime, workflow.adaptationStrategyId!)
          : await readPlan(runtime, workflow.seasonPlanId!);
      const before = await (
        await runtime.request(`/api/v2/chapters/${chapter.id}`)
      ).json();
      const db = openDatabase(path);
      try {
        db.uow.execute((tx) => {
          const row = tx.get<{ value_json: string }>(
            "SELECT value_json FROM automation_creation_workflows WHERE id=?",
            workflow.id,
          )!;
          const value = JSON.parse(row.value_json);
          value.issues = [
            {
              severity: "error",
              source: "model",
              message: "合成历史严重因果矛盾",
              evidence: "原正文保留。",
              location: "实际所选方案",
              suggestion: "保持原来源修订复检",
            },
          ];
          tx.run(
            "UPDATE automation_creation_workflows SET value_json=? WHERE id=?",
            JSON.stringify(value),
            workflow.id,
          );
        });
      } finally {
        db.close();
      }
      const stale = { ...candidate, stateVersion: candidate.stateVersion + 1 };
      const precondition =
        operation === "adaptation-strategy"
          ? await strategyAction(runtime, stale as AdaptationStrategy, "adopt")
          : await planAction(runtime, stale as SeasonPlan, "adopt");
      expect(precondition.status, await precondition.clone().text()).toBe(412);
      const response =
        operation === "adaptation-strategy"
          ? await strategyAction(
              runtime,
              candidate as AdaptationStrategy,
              "adopt",
            )
          : await planAction(runtime, candidate as SeasonPlan, "adopt");
      expect(response.status, await response.clone().text()).toBe(409);
      expect(
        operation === "adaptation-strategy"
          ? await readStrategy(runtime, candidate.id)
          : await readPlan(runtime, candidate.id),
      ).toEqual(candidate);
      expect(await readPlan(runtime, data.plan.id)).toEqual(oldPlan);
      expect(
        await (await runtime.request(`/api/v2/chapters/${chapter.id}`)).json(),
      ).toEqual(before);
    }, 20000);
  }

