  it("freezes only the adopted eight-field intent through generation, check, repair and recheck; a changed head rejects adoption without changing body", async () => {
    const sent: string[] = [];
    let release!: () => void;
    const gate = new Promise<void>((resolve) => {
      release = resolve;
    });
    let checks = 0;
    const runtime = await fixture(
      undefined,
      host(async (prompt) => {
        sent.push(prompt);
        if (prompt.includes("审阅候选与冻结"))
          return JSON.stringify({
            issues:
              checks++ === 0
                ? [
                    {
                      severity: "error",
                      message: "对白过于强硬",
                      evidence: "门",
                      location: "第一段",
                      suggestion: "修订对白",
                      source: "model",
                    },
                  ]
                : [],
          });
        if (sent.length === 1) await gate;
        return JSON.stringify({
          title: "第一章",
          content: "林晚推开门，终于看清来人。",
          items: [],
        });
      }),
    );
    const { project, chapter } = await seed(runtime);
    const original = await (
      await runtime.request(`/api/v2/projects/${project.id}`)
    ).json();
    const adopted = await adoptIntent(
      runtime,
      project.id,
      intentContent("OLD 正式主题"),
    );
    const pending = await previewIntent(
      runtime,
      project.id,
      intentContent("PRIVATE 尚未采用主题"),
    );
    const created = await start(runtime, {
      projectId: project.id,
      targetId: chapter.id,
      baseVersion: chapter.version,
    });
    try {
      await expect.poll(() => sent.length).toBe(1);
      const newer = await adoptIntent(
        runtime,
        project.id,
        intentContent("NEW 替换后的主题"),
      );
      expect(
        await (await runtime.request(`/api/v2/projects/${project.id}`)).json(),
      ).toEqual(original);
      release();
      const ready = await until(runtime, created.id, [
        "awaiting-review",
        "failed",
      ]);
      expect(ready.stage, ready.error).toBe("awaiting-review");
      expect(ready.runIds).toHaveLength(4);
      expect(ready.authorIntent).toEqual({
        state: "adopted",
        projectId: project.id,
        id: adopted.id,
        version: adopted.version,
      });
      expect(ready.sources).toContainEqual({
        kind: "author-intent",
        id: adopted.id,
        version: adopted.version,
      });
      expect(ready.referenceVersions).toContainEqual({
        sourceId: adopted.id,
        sourceVersion: adopted.version,
        fieldPath: "/author-intents/current",
      });
      for (const prompt of sent) {
        expect(prompt).toContain(
          `author_intent:${adopted.id}@${adopted.version}`,
        );
        expect(prompt).toContain(JSON.stringify(adopted.content));
        expect(prompt).not.toContain(pending.content.themeStatement);
        expect(prompt).not.toContain(newer.content.themeStatement);
      }
      const committed = await commitCreation(runtime, ready.previewId!);
      expect(committed.status, await committed.clone().text()).toBe(409);
      expect(
        (await until(runtime, created.id, ["awaiting-review"])).error,
      ).toContain("作者意图");
      expect(
        await (await runtime.request(`/api/v2/chapters/${chapter.id}`)).json(),
      ).toMatchObject({ content: "原正文保留。", version: chapter.version });
      const snapshot = await (
        await runtime.request(
          `/api/v2/agent-runs/${ready.runIds[0]}/context-snapshot`,
        )
      ).json();
      const entry = snapshot.entries.find(
        (value: { sourceKind: string }) => value.sourceKind === "author_intent",
      );
      expect(entry.value).toEqual({
        id: adopted.id,
        projectId: project.id,
        version: adopted.version,
        title: "正式作者意图",
        content: adopted.content,
      });
      expect(entry.value).not.toHaveProperty("source");
      expect(entry.value).not.toHaveProperty("stateVersion");
    } finally {
      release();
    }
  }, 15000);

