  it("author shot-plan field merge rejects substituted protocols and complete privacy ancestry before allocation then retries only the frozen selected expression after SQLite restart", async () => {
    const directory = await mkdtemp(
      join(tmpdir(), "dramaip-shot-merge-retry-"),
    );
    temporaryDirectories.push(directory);
    const path = join(directory, "runtime.sqlite"),
      data = await authorShotPlanMergeFixture(path);
    const { structureHash: _hash, ...legacy } = data.input;
    for (const invalid of [
      { ...legacy, format: "storyboard-record-field-merge-request-v1" },
      { ...data.input, format: "storyboard-record-field-merge-request-v2" },
      { ...data.input, structureHash: "f".repeat(64) },
      { ...data.input, scenePlans: data.request.redoShotPlan!.scenePlans },
      {
        ...data.input,
        choices: { ...data.input.choices, [`${data.old.id}:时长`]: "branch" },
      },
    ]) {
      const before = data.runtime.scriptMergeStorage(),
        counts = data.runtime.allocationCounts(),
        calls = data.sent.length;
      expect([400, 409]).toContain(
        (await data.submit(data.runtime, invalid)).status,
      );
      expect(data.runtime.scriptMergeStorage()).toEqual(before);
      expect(data.runtime.allocationCounts()).toEqual(counts);
      expect(data.sent.length).toBe(calls);
    }
    let policyVersion = 0;
    const policy = async (fieldPath?: string) => {
      const response = await data.runtime.request(
        `/api/v2/projects/${data.project.id}/agent-context-policies`,
        {
          method: "PUT",
          headers: { "If-Match": `"${policyVersion}"` },
          body: JSON.stringify({
            version: policyVersion,
            policies: fieldPath ? [{ fieldPath, mode: "never" }] : [],
          }),
        },
      );
      expect(response.status).toBe(200);
      policyVersion++;
    };
    for (const fieldPath of [
      `/production/${data.old.id}/payload/镜头描述`,
      `/production/${data.old.id}`,
      `/production/${data.sceneRecord.id}`,
      `/production/${data.comparison.structure.script.id}`,
      `/production/${data.comparison.structure.scriptRecordId}`,
    ]) {
      await policy(fieldPath);
      const counts = data.runtime.allocationCounts(),
        rows = data.runtime.scriptMergeStorage(),
        calls = data.sent.length;
      expect((await data.submit()).status).toBe(409);
      expect(data.runtime.allocationCounts()).toEqual(counts);
      expect(data.runtime.scriptMergeStorage()).toEqual(rows);
      expect(data.sent.length).toBe(calls);
    }
    await policy();
    const key = crypto.randomUUID();
    data.fault.recordMergeCheckRemaining = 1;
    const response = await data.submit(data.runtime, data.input, key);
    expect(response.status).toBe(200);
    const failed = await until(data.runtime, (await response.json()).id, [
        "failed",
      ]),
      calls = data.sent.length;
    await data.runtime.close();
    const restored = await fixture(undefined, data.engine, path, true);
    expect(
      (await (await data.submit(restored, data.input, key)).json()).id,
    ).toBe(failed.id);
    expect(data.sent.length).toBe(calls);
    const retry = await restored.request(
      `/api/v2/workflows/creation/${failed.id}/actions`,
      {
        method: "POST",
        headers: {
          "If-Match": `"${failed.version}"`,
          "Idempotency-Key": crypto.randomUUID(),
        },
        body: JSON.stringify({ action: "retry" }),
      },
    );
    expect(retry.status).toBe(200);
    const pending = await until(restored, (await retry.json()).id, [
      "awaiting-review",
    ]);
    expect(pending.recordMergeSource).toEqual(failed.recordMergeSource);
    expect(pending.output).toEqual(failed.output);
    expect(pending.sourceSnapshotId).toBe(failed.sourceSnapshotId);
    expect(data.sent.slice(calls)).toHaveLength(1);
    expect(data.sent.slice(calls).join("\n")).not.toContain("计划复用私人原值");
    expect((await commitCreation(restored, pending.previewId!)).status).toBe(
      200,
    );
    const actual = (await (
      await restored.request(`/api/v2/shots/${data.old.id}`)
    ).json()) as ProductionRecord;
    expect(actual).toMatchObject({
      title: data.actual.title,
      orderIndex: 1,
      version: data.actual.version + 1,
      payload: {
        时长: 20,
        镜头描述: data.actual.payload.镜头描述,
        私有旁注: data.actual.payload.私有旁注,
      },
    });
  }, 45000);
