  for (const conflict of [
    "same-version-selected",
    "unselected",
    "actual-document",
    "adoption-transaction",
  ] as const) {
    it(`author shot-plan field merge rejects ${conflict} without new identities, partial structural writes or events`, async () => {
      const data = await authorShotPlanMergeFixture(),
        response = await data.submit();
      expect(response.status).toBe(200);
      const pending = await until(data.runtime, (await response.json()).id, [
        "awaiting-review",
      ]);
      if (conflict === "actual-document") {
        const document = (await (
          await data.runtime.request(
            `/api/v2/scripts/${data.base.scriptId}/screenplay`,
          )
        ).json()) as ScreenplayDocument;
        const blocks = structuredClone(document.blocks),
          action = blocks.find((block) => block.type === "action")!;
        if (action.type !== "action") throw new Error("action required");
        action.text += " 作者另改，不自动换源。";
        expect(
          (
            await data.runtime.request(
              `/api/v2/scripts/${data.base.scriptId}/screenplay`,
              {
                method: "PATCH",
                headers: { "If-Match": `"${document.version}"` },
                body: JSON.stringify({ version: document.version, blocks }),
              },
            )
          ).status,
        ).toBe(200);
      } else if (conflict === "adoption-transaction")
        data.runtime.failStoryboardAdoption(true);
      else
        data.runtime.corruptStoryboardRecord(
          conflict === "same-version-selected"
            ? data.old.id
            : data.base.productionRecords!.find(
                (row) => row.kind === "shots" && row.id !== data.old.id,
              )!.id,
        );
      const rows = data.runtime.scriptMergeStorage().productionRecords,
        baseline = data.runtime.storyboardBaselineStorage(data.base.id),
        events = data.runtime
          .domainEvents()
          .filter((event) => event.pluginId === "production"),
        calls = data.sent.length;
      expect(
        (await commitCreation(data.runtime, pending.previewId!)).status,
      ).toBe(409);
      expect(data.runtime.scriptMergeStorage().productionRecords).toEqual(rows);
      expect(data.runtime.storyboardBaselineStorage(data.base.id)).toEqual(
        baseline,
      );
      expect(
        data.runtime
          .domainEvents()
          .filter((event) => event.pluginId === "production"),
      ).toEqual(events);
      expect(data.sent.length).toBe(calls);
    }, 35000);
  }

