  it("cancels the real executor and ignores its delayed output before an idempotent task-centre retry", async () => {
    let release!: (value: string) => void;
    let calls = 0;
    let aborted = 0;
    const engine = host((prompt) => {
      calls++;
      if (calls === 1)
        return new Promise<string>((resolve) => {
          release = resolve;
        });
      return JSON.stringify(
        prompt.includes("审阅候选与冻结")
          ? { issues: [] }
          : {
              title: "新运行",
              content: "林晚推开门，终于看清来人。",
              items: [],
            },
      );
    });
    const operation = engine.engineOperation.bind(engine);
    engine.engineOperation = async (
      ...args: Parameters<typeof engine.engineOperation>
    ) => {
      if (args[1] === "cancel") aborted++;
      return operation(...args);
    };
    const runtime = await fixture(undefined, engine);
    const { project, chapter } = await seed(runtime);
    const created = await start(runtime, {
      projectId: project.id,
      targetId: chapter.id,
      baseVersion: chapter.version,
    });
    for (let count = 0; count < 60 && !release; count++)
      await new Promise((resolve) => setTimeout(resolve, 50));
    expect(release).toBeDefined();
    const canceled = await runtime.request(
      `/api/v2/tasks/${created.taskId}/cancel`,
      { method: "POST" },
    );
    expect(canceled.status, await canceled.clone().text()).toBe(200);
    expect(aborted).toBeGreaterThan(0);
    release(
      JSON.stringify({
        title: "过期",
        content: "不应被采用的延迟结果",
        items: [],
      }),
    );
    const key = crypto.randomUUID();
    const retry = () =>
      runtime.request(`/api/v2/tasks/${created.taskId}/retry`, {
        method: "POST",
        headers: { "Idempotency-Key": key },
        body: "{}",
      });
    const retryResponse = await retry();
    expect(retryResponse.status, await retryResponse.clone().text()).toBe(200);
    const task = (await retryResponse.json()) as {
      id: string;
      result: { creationWorkflowId: string };
    };
    expect(((await (await retry()).json()) as { id: string }).id).toBe(task.id);
    const ready = await until(runtime, task.result.creationWorkflowId, [
      "awaiting-review",
      "failed",
    ]);
    expect(ready.stage, ready.error).toBe("awaiting-review");
    expect(ready.output?.title).toBe("新运行");
    const old = await until(runtime, created.id, ["canceled"]);
    expect(old.previewId).toBeUndefined();
  }, 15000);

  async function legacyProductionSources(runtime: Fixture) {
    const { project, chapter } = await seed(runtime);
    const chapters = [chapter];
    for (let index = 1; index < 5; index++) {
      const response = await runtime.request("/api/v2/chapters", {
        method: "POST",
        body: JSON.stringify({
          projectId: project.id,
          title: `第 ${index + 1} 章`,
          content: `PRIVATE_LEGACY_SOURCE_${index + 1}_不应隐式发送。`,
        }),
      });
      expect(response.status, await response.clone().text()).toBe(201);
      chapters.push(await response.json());
    }
    const record = async (kind: string, parentId?: string, payload = {}) => {
      const response = await runtime.request(`/api/v2/${kind}`, {
        method: "POST",
        body: JSON.stringify({
          projectId: project.id,
          parentId,
          title: kind,
          payload,
        }),
      });
      expect(response.status, await response.clone().text()).toBe(201);
      return (await response.json()) as { id: string; version: number };
    };
    const adaptation = await record("adaptations");
    const episode = await record("episodes", adaptation.id);
    const script = await record("scripts", episode.id, {
      剧本内容: "INT. HALL - NIGHT\n\n阿禾打开门。",
    });
    const scene = await record("scenes", script.id);
    const shot = await record("shots", scene.id, { 时长: "5" });
    return { project, chapters, episode, script, shot };
  }
  function legacyProductionOutput(prompt: string) {
    if (
      prompt.includes("审阅候选与冻结") ||
      prompt.includes("针对已采用剧本与原审片意见做复检")
    )
      return JSON.stringify({ issues: [] });
    const blocks = [
      {
        id: crypto.randomUUID(),
        type: "scene_heading",
        text: "INT. HALL - NIGHT",
      },
      { id: crypto.randomUUID(), type: "action", text: "阿禾打开门。" },
    ];
    const content = blocks.map((block) => block.text).join("\n\n");
    if (prompt.includes("按反馈局部修订本集剧本"))
      return JSON.stringify({
        title: "兼容修订",
        content,
        items: blocks.map((block) => ({
          ref: block.id,
          kind: "screenplay-block",
          title: block.type,
          data: block,
        })),
      });
    if (prompt.includes("完善媒体提示词"))
      return JSON.stringify({
        title: "镜头提示",
        content: "雨夜门厅，手推木门，克制自然光。",
        items: [],
      });
    return JSON.stringify({
      title: "兼容分集",
      content,
      items: [
        {
          ref: "s",
          kind: "scripts",
          title: "剧本",
          data: { 剧本内容: content },
        },
        {
          ref: "c",
          parentRef: "s",
          kind: "scenes",
          title: "门厅",
          data: { 场景动作: "开门" },
        },
        {
          ref: "h",
          parentRef: "c",
          kind: "shots",
          title: "开门",
          data: { 生成提示: "手推木门", 时长: "5" },
        },
      ],
    });
  }

