  it("production narrative privacy covers project and saved targets, complete instruction budget and missing documents reject with no allocations or owner writes", async () => {
    const sent: string[] = [];
    const runtime = await fixture(
      undefined,
      host((prompt) => {
        sent.push(prompt);
        return legacyProductionOutput(prompt);
      }),
    );
    const data = await legacyProductionSources(runtime),
      chapter = data.chapters[3]!;
    const input = {
      projectId: data.project.id,
      operation: "episode",
      targetId: data.episode.id,
      baseVersion: data.episode.version,
      sourceIds: [],
      productionNarrativeRequest: productionOriginalRequest(chapter),
      engineKind: "codex",
      model: { modelId: "test-fixed-model" },
      instruction: "必须完整保留明确表达与约束",
    };
    const reject = async (extra: Record<string, unknown> = {}) => {
      const before = runtime.allocationCounts(),
        events = runtime.domainEvents(),
        owner = runtime.scriptMergeStorage();
      const response = await runtime.request("/api/v2/workflows/creation", {
        method: "POST",
        headers: { "Idempotency-Key": crypto.randomUUID() },
        body: JSON.stringify({ ...input, ...extra }),
      });
      expect(response.status, await response.clone().text()).toBe(409);
      expect(runtime.allocationCounts()).toEqual(before);
      expect(runtime.domainEvents()).toEqual(events);
      expect(runtime.scriptMergeStorage()).toEqual(owner);
      expect(sent).toEqual([]);
    };
    runtime.forgetLegacyScriptDocument(data.script.id);
    await reject({
      operation: "script-revision",
      targetId: data.script.id,
      baseVersion: data.script.version,
    });
    const policy = async (
      version: number,
      fieldPath: string,
      mode: "never" | "auto",
    ) => {
      const response = await runtime.request(
        `/api/v2/projects/${data.project.id}/agent-context-policies`,
        {
          method: "PUT",
          headers: { "If-Match": `"${version}"` },
          body: JSON.stringify({
            version,
            policies: [
              `/chapters/${chapter.id}`,
              "/project",
              `/production/${data.episode.id}`,
            ].map((path) => ({
              fieldPath: path,
              mode: path === fieldPath ? mode : "auto",
            })),
          }),
        },
      );
      expect(response.status, await response.clone().text()).toBe(200);
    };
    await policy(0, `/chapters/${chapter.id}`, "never");
    await reject();
    await policy(1, `/project`, "never");
    await reject();
    await policy(2, `/production/${data.episode.id}`, "never");
    await reject();
    await policy(3, `/production/${data.episode.id}`, "auto");
    await reject({ instruction: "大".repeat(95000) });
    const changed = await runtime.request(`/api/v2/chapters/${chapter.id}`, {
      method: "PATCH",
      headers: { "If-Match": `"${chapter.version}"` },
      body: JSON.stringify({
        version: chapter.version,
        content: "大".repeat(180000),
      }),
    });
    expect(changed.status, await changed.clone().text()).toBe(200);
    await reject({
      productionNarrativeRequest: productionOriginalRequest(
        await changed.json(),
      ),
    });
  }, 20000);

  it("production narrative review-check refuses a source changed during the actual run instead of auto-marking it applied", async () => {
    let release!: () => void, entered!: () => void;
    const waiting = new Promise<void>((resolve) => {
        release = resolve;
      }),
      started = new Promise<void>((resolve) => {
        entered = resolve;
      });
    const sent: string[] = [];
    const runtime = await fixture(
      undefined,
      host(async (prompt) => {
        sent.push(prompt);
        entered();
        await waiting;
        return JSON.stringify({ issues: [] });
      }),
    );
    const data = await legacyProductionSources(runtime),
      chapter = data.chapters[3]!;
    expect(
      (await runtime.request(`/api/v2/scripts/${data.script.id}/screenplay`))
        .status,
    ).toBe(200);
    const created = await start(runtime, {
      projectId: data.project.id,
      operation: "review-check",
      targetId: data.script.id,
      baseVersion: data.script.version,
      sourceIds: [],
      wordGoal: undefined,
      productionNarrativeRequest: productionOriginalRequest(chapter),
    });
    await started;
    try {
      expect(
        (
          await runtime.request(`/api/v2/chapters/${chapter.id}`, {
            method: "PATCH",
            headers: { "If-Match": `"${chapter.version}"` },
            body: JSON.stringify({
              version: chapter.version,
              content: "PRIVATE_CHANGED_DURING_REVIEW",
            }),
          })
        ).status,
      ).toBe(200);
    } finally {
      release();
    }
    const failed = await until(runtime, created.id, ["failed", "applied"]);
    expect(failed.stage, failed.error).toBe("failed");
    expect(failed.previewId).toBeUndefined();
    expect(failed.productionNarrativeBasis?.request).toEqual(
      productionOriginalRequest(chapter),
    );
    expect(sent).toHaveLength(1);
    expect(sent[0]).toContain("PRIVATE_LEGACY_SOURCE_4_");
    expect(sent[0]).not.toContain("PRIVATE_CHANGED_DURING_REVIEW");
  }, 15000);

